        // Render Views

        // Form Submission Handlers
        // Batas ukuran file upload (voice sample & sample hasil edit) — sejalan dengan
        // batas maksimal blob 50MB di Google Apps Script. Mengecek SEBELUM file
        // diproses jadi base64, supaya file kegedean tidak sampai bikin tab browser
        // kehabisan memori (base64 membengkakkan ukuran file sekitar 33%).
        const MAX_UPLOAD_SIZE_MB = 50;
        function isFileSizeOk(file) {
            if (!file) return true;
            return file.size <= MAX_UPLOAD_SIZE_MB * 1024 * 1024;
        }

        function readFileAsBase64(file) {
            return new Promise((resolve, reject) => {
                if (!file) { resolve(null); return; }
                const reader = new FileReader();
                reader.onload = () => resolve({ name: file.name, type: file.type, data: reader.result });
                reader.onerror = reject;
                reader.readAsDataURL(file);
            });
        }

        // Baca banyak file gambar sekaligus (untuk foto produk toko) dan kembalikan array data URL
        async function readFilesAsBase64Array(fileList) {
            const files = Array.from(fileList || []);
            const results = [];
            for (const f of files) {
                const uploaded = await readFileAsBase64(f);
                if (uploaded) results.push(uploaded.data);
            }
            return results;
        }

        // Foto/berkas kecil disimpan langsung di database (Firestore), bukan Google Drive.
        // Gambar otomatis diperkecil (JPEG) supaya hasilnya jauh di bawah 600 KB; berkas lain (mis. PDF) maks. 600 KB.
        const MAX_ADMIN_FILE_KB = 600;
        async function uploadMediaFiles(fileList, prefix, maxChars) {
            const files = Array.from(fileList || []).filter(Boolean);
            const out = [];
            for (const file of files) {
                if (file.type && file.type.startsWith('image/')) {
                    out.push(await shrinkImageFile(file, 1000, maxChars || 250000));
                } else {
                    if (file.size > MAX_ADMIN_FILE_KB * 1024) {
                        throw new Error(`File "${file.name}" terlalu besar (${Math.round(file.size / 1024)} KB). Maksimal ${MAX_ADMIN_FILE_KB} KB.`);
                    }
                    out.push((await readFileAsBase64(file)).data);
                }
            }
            return out;
        }

