function toggleAnnouncement(id) {
    const body = document.getElementById('annBody_' + id), btn = document.getElementById('annBtn_' + id);
    if (!body || !btn) return;
    const open = body.classList.toggle('hidden') === false;
    btn.textContent = open ? 'Tutup' : 'Baca selengkapnya';
    if (typeof uiSound === 'function') uiSound('tap');
}
