const $id = id => document.getElementById(id);


function vsGroup(id) { return (appData.verseGroups || []).find(g => g.id === id) || null; }
function vsArtist(id) { return (appData.verseArtists || []).find(a => a.id === id) || null; }
// Peran (artis / akun grup) hanya sah bila dokumen verseStaff milik email Google ini cocok dengan "staffVer" di data artis/grup.
function vsStaff() {
    const st = VAUTH.staffRaw; if (!st) return null;
    const rec = st.kind === 'group' ? vsGroup(st.refId) : vsArtist(st.refId);
    return (rec && rec.staffVer && rec.staffVer === st.ver) ? st : null;
}
function vsSession() { const st = vsStaff(); return st && st.kind === 'artist' ? vsArtist(st.refId) : null; }          // akun artis yang masuk
function vsGroupSession() { const st = vsStaff(); return st && st.kind === 'group' ? vsGroup(st.refId) : null; }       // akun grup yang masuk
function vsIsAdmin() { return typeof isAdminLoggedIn !== 'undefined' && isAdminLoggedIn; }
function vsSlug(t) { return String(t || '').replace(/[∅Øø]/g, 'o').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
function vsLoginLink(g) { return location.origin + '/' + vsSlug(g.slug || g.name) + 'login'; }
function vsMaskEmail(e) { const [u, d] = String(e).split('@'); return (u || '').slice(0, 2) + '***@' + (d || ''); }

// ---------- Login Google (Firebase Authentication) ----------
function vsHint() { try { return JSON.parse(localStorage.getItem('lorevia_vs_hint') || 'null'); } catch (e) { return null; } }
function vsSetHint(u) { try { if (u) localStorage.setItem('lorevia_vs_hint', JSON.stringify({ uid: u.uid })); else localStorage.removeItem('lorevia_vs_hint'); } catch (e) {} }
// Tanpa layar "memuat": bila perangkat ini pernah masuk, langsung tampilkan aplikasi selagi login dipulihkan di latar belakang.
function vsCanView() { return !!(VAUTH.user || vsIsAdmin() || (!VAUTH.ready && vsHint())); }
function vsAuthStart() {
    if (VAUTH.started) return; VAUTH.started = true;
    if (!window.loreviaAuth) { VAUTH.ready = true; VAUTH.err = 'Layanan login belum siap.'; return; }
    window.loreviaAuth.onChange(vsAuthSync);
    window.loreviaAuth.start().catch(e => { VAUTH.ready = true; VAUTH.err = vsAuthErr(e) || 'Tidak bisa terhubung ke layanan login.'; if (window.PAGE_ROUTE === 'verse') renderView(); });
}
async function vsAuthSync(u) {
    VAUTH.user = u; VAUTH.staffRaw = null; VAUTH.profile = null; VAUTH.err = ''; VAUTH.joinedNow = false;
    vsSetHint(u);
    if (u) {
        let st = null, pr = null, perr = false;
        try { if (window.loreviaDbReady) await Promise.race([window.loreviaDbReady, new Promise(r => setTimeout(r, 6000))]); if (window.loreviaDbEnsure) await window.loreviaDbEnsure('verse'); } catch (e) {}
        try { st = await window.loreviaDoc.get('verseStaff', u.email); } catch (e) { console.warn('[Verse] peran:', e); }
        try { pr = await window.loreviaDoc.get('verseProfiles', u.uid); } catch (e) { perr = true; console.warn('[Verse] profil:', e); }
        if (pr) vsProfCache(u.uid, pr);
        else { const c = vsProfCache(u.uid); if (c) { pr = c; if (!perr) window.loreviaDoc.set('verseProfiles', u.uid, c).catch(() => {}); } }   // cadangan lokal: nama/foto tidak hilang
        VAUTH.staffRaw = st; VAUTH.profile = pr;
    }
    VAUTH.ready = true; VSB.all = null; VSB.mine = []; VSL.mine = null; VSL.inbox = null; VSV.eventId = ''; VS.mentions = null;
    if (window.PAGE_ROUTE === 'verse' || currentRoute === 'verse') renderView();
    if (VS.wantAnim && u && !vsNeedReg()) { VS.wantAnim = false; vsLoginAnim((vsSession() || vsGroupSession() || {}).name || vsFanName()); }
}
// Cadangan profil di browser (dibaca bila server gagal / dokumen belum tersimpan)
function vsProfCache(uid, val) {
    try { const k = 'lorevia_vs_prof_' + uid; if (val === undefined) return JSON.parse(localStorage.getItem(k) || 'null'); localStorage.setItem(k, JSON.stringify(val)); } catch (e) {}
    return null;
}
function vsNeedReg() { return !!(VAUTH.user && VAUTH.ready && !vsStaff() && !(VAUTH.profile && VAUTH.profile.username)); }
function vsAuthErr(e) {
    const c = String((e && (e.code || e.message)) || e);
    if (/popup-closed|cancelled-popup|user-cancelled/.test(c)) return '';
    if (/unauthorized-domain/.test(c)) return 'Domain situs ini belum diizinkan di Firebase Authentication (Authorized domains).';
    if (/operation-not-allowed|configuration-not-found/.test(c)) return 'Login Google belum diaktifkan di Firebase Authentication.';
    if (/network|offline/.test(c)) return 'Tidak ada koneksi internet.';
    if (/disallowed_useragent|web-storage-unsupported|operation-not-supported/.test(c)) return 'Browser aplikasi ini tidak mendukung login Google. Buka lewat Chrome/Safari.';
    if (/permission|insufficient/.test(c)) return 'Aturan database (rules) belum dipublikasikan atau menolak aksi ini.';
    return 'Gagal masuk: ' + c.slice(0, 100);
}
async function vsGoogle() {
    if (VAUTH.busy) return; VS.wantAnim = true; VAUTH.busy = true; VAUTH.err = ''; renderView();
    try { await window.loreviaAuth.signInGoogle(); } catch (e) { VAUTH.err = vsAuthErr(e); }
    VAUTH.busy = false; renderView();
}
async function vsLogout() {
    vsModalClose(); vsDrawerClose();
    try { await window.loreviaAuth.signOut(); } catch (e) { console.warn(e); }
    VS.tab = 'home'; VS.artistId = null; VSF.posts = null; renderView();
}
function vsWelcome() {
    try { const k = 'lorevia_vs_wel_' + ((VAUTH.user || {}).uid || ''); if (localStorage.getItem(k)) return; localStorage.setItem(k, '1'); } catch (e) {}
    const g = (appData.verseGroups || []).length, a = (appData.verseArtists || []).length;
    vsModal(`<div class="vs-wel"><span class="vs-wel-logo">${LOGO_VERSE}</span><h3>Selamat datang di Lorevia Verse!</h3>
        <p>Kamu otomatis mengikuti <b>${g} komunitas</b> dan <b>${a} artis</b>. Kamu bisa berhenti mengikuti kapan saja lewat halaman komunitas atau artis.</p>
        <button type="button" class="vs-btn" onclick="vsModalClose()">Mulai jelajah</button></div>`);
}

// ---------- Profil pengguna, ikuti, gambar ----------
function vsProf() { return VAUTH.profile || {}; }
function vsMyPhoto() { return vsProf().photo || (VAUTH.user && VAUTH.user.photo) || ''; }
async function vsSaveProf(patch) {
    const u = VAUTH.user; if (!u) throw new Error('Belum masuk');
    const p = Object.assign({ unfollow: [], follow: [], joined: Date.now() }, VAUTH.profile || {}, patch, { uid: u.uid, ts: Date.now() });
    await window.loreviaDoc.set('verseProfiles', u.uid, p); VAUTH.profile = p; return p;
}
function vsFollowBtn(id, big) {
    const f = vsFollowing(id);
    return `<button type="button" class="vs-fol ${f ? 'on' : ''} ${big ? 'big' : ''}" onclick="vsToggleFollow('${id}')">${f ? 'Mengikuti' : 'Ikuti'}</button>`;
}
function vsReadFile(f) { return new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => rej(new Error('Gagal membaca file')); r.readAsDataURL(f); }); }
function vsShrink(src, w, h, q) {
    return new Promise((res, rej) => {
        const im = new Image();
        im.onload = () => {
            const c = document.createElement('canvas'); c.width = w; c.height = h; const x = c.getContext('2d');
            const s = Math.max(w / im.width, h / im.height), dw = im.width * s, dh = im.height * s;
            x.fillStyle = '#fff'; x.fillRect(0, 0, w, h); x.drawImage(im, (w - dw) / 2, (h - dh) / 2, dw, dh);
            res(c.toDataURL('image/jpeg', q || .8));
        };
        im.onerror = () => rej(new Error('Gambar tidak bisa dibaca')); im.src = src;
    });
}
async function vsLoadFan(force) {
    if (VSF.loading || (VSF.posts && !force)) return;
    VSF.loading = true;
    try {
        const L = vsLikedSet();
        const rows = await window.loreviaDoc.recent('verseFanPosts', 60);
        VSF.posts = rows.map(r => { r.fan = true; r.id = r._id; r._liked = !!L['fp_' + r._id]; if (typeof r.likes !== 'number') r.likes = 0; return r; });
    } catch (e) { console.warn('[Verse] postingan penggemar:', e); VSF.posts = VSF.posts || []; }
    VSF.loading = false;
    if (currentRoute === 'verse' && !document.getElementById('vsModal')?.classList.contains('open')) renderView();
}
function vsLikedSet() { try { return JSON.parse(localStorage.getItem('lorevia_liked') || '{}') || {}; } catch (e) { return {}; } }
function vsFanName() { const u = VAUTH.user; return (VAUTH.profile && VAUTH.profile.nickname) || (u && (u.name || String(u.email).split('@')[0])) || ''; }

function vsUnlockedList() { try { return JSON.parse(localStorage.getItem('lorevia_vs_unlocked') || '[]') || []; } catch (e) { return []; } }
function vsRp(n) { return 'Rp' + (parseInt(n, 10) || 0).toLocaleString('id-ID'); }
function vsAgo(ts) {
    const s = Math.max(1, Math.floor((Date.now() - (ts || 0)) / 1000));
    if (s < 60) return 'baru saja';
    if (s < 3600) return Math.floor(s / 60) + ' menit lalu';
    if (s < 86400) return Math.floor(s / 3600) + ' jam lalu';
    if (s < 2592000) return Math.floor(s / 86400) + ' hari lalu';
    return new Date(ts).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
}
function vsStoriesOf(artistId) {
    const cut = Date.now() - 86400000;
    return (appData.verseStories || []).filter(s => s.artistId === artistId && (s.ts || 0) > cut).sort((a, b) => a.ts - b.ts);
}
function vsIsOwner(p) { const me = vsSession(), gs = vsGroupSession(); return !!(me && p.authorType === 'artist' && p.authorId === me.id) || !!(gs && p.authorType === 'group' && p.authorId === gs.id) || vsIsAdmin(); }
function vsLocked(p) { return !!p.exclusive && !vsIsOwner(p) && vsUnlockedList().indexOf(p.id) < 0; }


// ---------- Spotify: tautan, deteksi judul lagu & pencipta/artis ----------
function vsSpotify(url) {
    const m = String(url || '').trim().match(/open\.spotify\.com\/(?:intl-[a-z]+\/)?(track|album|playlist|episode|show|artist)\/([A-Za-z0-9]+)/);
    return m ? { type: m[1], id: m[2], url: 'https://open.spotify.com/' + m[1] + '/' + m[2] } : null;
}
const VS_SPC = {};
function vsMeta(html, prop) {
    const m = html.match(new RegExp('<meta[^>]+(?:property|name)="' + prop + '"[^>]+content="([^"]*)"', 'i')) || html.match(new RegExp('<meta[^>]+content="([^"]*)"[^>]+(?:property|name)="' + prop + '"', 'i'));
    return m ? m[1].replace(/&amp;/g, '&').replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"') : '';
}
// 1) oEmbed resmi Spotify (judul + sampul).  2) Halaman Spotify lewat proxy CORS publik untuk mengambil nama artis/pencipta.
async function vsSpMeta(sp) {
    const key = sp.type + '_' + sp.id;
    if (VS_SPC[key]) return VS_SPC[key];
    const out = { title: '', artist: '', cover: '' };
    try {
        const r = await fetch('https://open.spotify.com/oembed?url=' + encodeURIComponent(sp.url));
        if (r.ok) { const j = await r.json(); out.title = String(j.title || ''); out.cover = String(j.thumbnail_url || ''); }
    } catch (e) {}
    if (!out.artist && sp.type !== 'artist') {
        const proxies = [u => 'https://api.allorigins.win/raw?url=' + encodeURIComponent(u), u => 'https://corsproxy.io/?url=' + encodeURIComponent(u)];
        for (const px of proxies) {
            try {
                const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), 6000);
                const r = await fetch(px(sp.url), { signal: ctl.signal }); clearTimeout(t);
                if (!r.ok) continue;
                const html = await r.text();
                const ogt = vsMeta(html, 'og:title'), ogd = vsMeta(html, 'og:description');
                if (ogt && !out.title) out.title = ogt;
                const img = vsMeta(html, 'og:image'); if (img && !out.cover) out.cover = img;
                // og:description Spotify: "Artis · Album · Lagu · 2023" atau "Artis · Lagu · 2023"
                if (ogd && ogd.indexOf('·') > 0) out.artist = ogd.split('·')[0].trim();
                if (!out.artist) { const tm = html.match(/<title>[^<]*?(?:by|oleh)\s+([^|<]+?)\s*\|/i); if (tm) out.artist = tm[1].trim(); }
                if (out.artist) break;
            } catch (e) {}
        }
    }
    out.title = out.title.slice(0, 200); out.artist = out.artist.slice(0, 200);
    if (out.title || out.artist) VS_SPC[key] = out;
    return out;
}
// Mengisi judul/artis untuk kartu Spotify yang belum punya data (postingan lama / artis)
function vsSpFill() {
    document.querySelectorAll('.vs-spm:not([data-done])').forEach(el => {
        el.setAttribute('data-done', '1');
        vsSpMeta({ type: el.dataset.t, id: el.dataset.i, url: el.dataset.u }).then(m => {
            const b = el.querySelector('b'), s = el.querySelector('.vs-mc-ar') || el.querySelectorAll('small')[el.classList.contains('vs-mc-meta') ? 1 : 0];
            if (m.title && b) b.textContent = m.title;
            if (s) s.textContent = m.artist || '';
            if (m.cover) { const box = el.closest('.vs-mc') || el.parentNode; box.querySelectorAll('.vs-mc-art, .vs-spc').forEach(x => { x.innerHTML = '<img src="' + escHtml(m.cover) + '" alt="">'; }); }
        });
    });
}

// ---------- Terjemahan (Korea / Jepang / Inggris / lainnya -> bahasa pilihan) ----------
const VS_TXT = {}; let VS_TN = 0; const VS_TRC = {};
function vsLang() { try { return localStorage.getItem('lorevia_vs_lang') || 'id'; } catch (e) { return 'id'; } }
function vsTx(text) { const k = 't' + (++VS_TN); VS_TXT[k] = text; return k; }
function vsTrBtn(text) {
    if (!text) return '';
    const k = vsTx(text), foreign = /[぀-ヿ㐀-鿿가-힯฀-๿Ѐ-ӿ؀-ۿ]/.test(text);
    return `<button type="button" class="vs-trb ${foreign ? 'hl' : ''}" id="vtb_${k}" onclick="vsTr('${k}')">${VS_ICON.globe}<span>${foreign ? 'Lihat terjemahan' : 'Terjemahkan'}</span></button><div class="vs-tr" id="vtr_${k}" hidden></div>`;
}
async function vsTrans(text) {
    const lang = vsLang(), ck = lang + '|' + text; if (VS_TRC[ck]) return VS_TRC[ck];
    let res = null;
    try {
        const r = await fetch('https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=' + lang + '&dt=t&q=' + encodeURIComponent(text.slice(0, 1500)));
        const j = await r.json(); res = { text: (j[0] || []).map(x => x[0]).join(''), src: j[2] || '' };
    } catch (e) {}
    if (!res || !res.text) {
        const r = await fetch('https://api.mymemory.translated.net/get?q=' + encodeURIComponent(text.slice(0, 450)) + '&langpair=autodetect|' + lang);
        const j = await r.json(); res = { text: (j.responseData && j.responseData.translatedText) || '', src: '' };
        if (!res.text) throw new Error('kosong');
    }
    VS_TRC[ck] = res; return res;
}
async function vsTr(k) {
    const box = $id('vtr_' + k), btn = $id('vtb_' + k); if (!box || !btn) return;
    const lab = btn.querySelector('span');
    if (!box.hidden) { box.hidden = true; lab.textContent = 'Lihat terjemahan'; return; }
    box.hidden = false; box.textContent = 'Menerjemahkan…';
    try {
        const r = await vsTrans(VS_TXT[k]); let from = '';
        try { if (r.src && r.src !== vsLang()) from = new Intl.DisplayNames([vsLang()], { type: 'language' }).of(r.src); } catch (e) {}
        box.innerHTML = `<small>${r.src === vsLang() ? 'Sudah dalam bahasa pilihanmu.' : 'Diterjemahkan' + (from ? ' dari ' + escHtml(from) : '') + ' ke ' + escHtml(VS_LANGS[vsLang()] || vsLang())}</small><p>${escHtml(r.text)}</p>`;
        lab.textContent = 'Sembunyikan terjemahan';
    } catch (e) { box.textContent = 'Terjemahan gagal. Periksa koneksi lalu coba lagi.'; }
}
function vsSetLang(v) { try { localStorage.setItem('lorevia_vs_lang', v); } catch (e) {} renderView(); }

// ---------- Kartu postingan ----------
function vsFindPost(id) { return (appData.versePosts || []).find(x => x.id === id) || (VSF.posts || []).find(x => x.id === id) || null; }
function vsPostHtml(p) {
    const fan = !!p.fan;
    const au = fan ? null : (p.authorType === 'artist' ? vsArtist(p.authorId) : vsGroup(p.authorId));
    const name = fan ? (p.name || 'Penggemar') : (au ? au.name : 'Lorevia');
    const photo = fan ? p.av : (au && (au.photo || au.avatar));
    const g = vsGroup(p.groupId);
    const open = fan ? '' : (p.authorType === 'artist' ? `onclick="vsOpenArtist('${p.authorId}')"` : `onclick="vsOpenGroup('${p.authorId}')"`);
    const locked = vsLocked(p);
    const photos = p.photos || [];
    let media = '';
    if (locked) {
        media = `<div class="vs-lockbox">${photos[0] ? `<img src="${escHtml(photos[0])}" alt="">` : '<div class="vs-lockbg"></div>'}
            <div class="vs-lockov">${VS_ICON.lock}<b>Konten eksklusif</b><span>${vsRp(p.price)}</span>
            <button type="button" class="vs-btn" onclick="vsUnlockOpen('${p.id}')">Buka konten</button></div></div>`;
    } else {
        if (photos.length) media += `<div class="vs-car" onscroll="vsCarScroll(this)">${photos.map(src => `<div class="vs-slide"><img src="${escHtml(src)}" alt="" loading="lazy"></div>`).join('')}</div>` +
            (photos.length > 1 ? `<div class="vs-dots">${photos.map((_, i) => `<i class="${i === 0 ? 'on' : ''}"></i>`).join('')}</div>` : '');
        if (p.audio) media += `<button type="button" class="vs-audio" onclick="vsPlayPost('${p.id}')"><span>${VS_ICON.play}</span><em>${escHtml(p.audio.title || 'Musik')}</em>${VS_ICON.note}</button>`;
    }
    const plv = fan ? vsUidLv(p.uid) : (p.authorType === 'artist' ? vsArtistLv(p.authorId) : 0);
    const music = (!locked && p.spotify) ? vsMusicCard(p.spotify, p.id) : '';
    const mineFan = fan && VAUTH.user && VAUTH.user.uid === p.uid;
    const owner = !fan && vsIsOwner(p);
    return `<article class="vs-post vs-glass" id="post_${p.id}">
        <div class="vs-ph-row"><button type="button" class="vs-ph" ${open}>${vsAv(photo, name, 'sm', plv)}</button><div><b ${open}>${escHtml(name)}${fan ? vsBadges(plv) : VS_VF}</b><span>${vsAgo(p.ts)}${fan && g ? ' · ' + escHtml(g.name) : ''}${p.exclusive ? ' · <u>Eksklusif ' + vsRp(p.price) + '</u>' : ''}</span></div></div>
        ${music}
        ${locked ? '' : (p.text ? `<p class="vs-text">${escHtml(p.text)}</p>${vsTrBtn(p.text)}` : '')}
        ${media}
        <div class="vs-foot"><div class="vs-acts"><button type="button" class="vs-like ${p._liked ? 'on' : ''}" onclick="vsLike('${p.id}')">${p._liked ? VS_ICON.heart : VS_ICON.heartO}<span id="vsl_${p.id}">${(p.likes || 0).toLocaleString('id-ID')}</span></button>
        <button type="button" class="vs-like" onclick="vsComments('${p.id}')">${VS_ICON.chat}<span>Komentar</span></button></div>
        ${owner ? `<span class="vs-own"><button type="button" onclick="vsToggleExclusive('${p.id}')">${p.exclusive ? 'Jadikan publik' : 'Jadikan eksklusif'}</button><button type="button" onclick="vsDeletePost('${p.id}')">Hapus</button></span>` : ''}
        ${mineFan ? `<span class="vs-own"><button type="button" onclick="vsDeletePost('${p.id}')">Hapus</button></span>` : ''}</div>
    <div class="vs-cm" id="vcm_${p.id}" hidden></div></article>`;
}
function vsMyName() { const me = vsSession(), gs = vsGroupSession(); if (me) return me.name; if (gs) return gs.name; return vsFanName() || (vsIsAdmin() ? 'Admin Lorevia' : ''); }
function vsMyAv() { const me = vsSession(), gs = vsGroupSession(), a = me ? me.photo : gs ? gs.photo : (vsProf().av || ''); return (a && a.length <= 14000) ? a : ''; }
function vsCommentHtml(c, pid) {
    const mine = !!(VAUTH.user && c.uid && c.uid === VAUTH.user.uid);
    const can = mine || vsIsAdmin() || (!c.uid && c.name === vsMyName());
    return `<div class="vs-c">${vsAv(c.av, c.name, 'xs', vsUidLv(c.uid))}<div class="vs-c-b"><div><b>${escHtml(c.name)}</b>${vsBadges(vsUidLv(c.uid))} <small>${vsAgo(c.ts)}</small></div><p>${escHtml(c.text)}</p>${vsTrBtn(c.text)}
        ${can ? `<button type="button" class="vs-link" onclick="vsDelComment('${pid}','${c._id}')">hapus</button>` : ''}</div></div>`;
}
async function vsComments(id) {
    const box = $id('vcm_' + id); if (!box) return;
    if (!box.hidden) { box.hidden = true; return; }
    box.hidden = false; box.innerHTML = '<small class="vs-mut">Memuat komentar…</small>';
    try {
        const rows = await window.loreviaComments.list(id);
        box.innerHTML = `<div class="vs-cmh">${rows.length} komentar</div>` + (rows.length ? rows.map(c => vsCommentHtml(c, id)).join('') : '<small class="vs-mut">Jadilah yang pertama berkomentar.</small>')
            + `<div class="vs-cform"><input id="vci_${id}" maxlength="500" placeholder="Tulis komentar…" onkeydown="if(event.key==='Enter')vsSendComment('${id}')"><button type="button" class="vs-btn sm" onclick="vsSendComment('${id}')">Kirim</button></div>`;
    } catch (e) { box.innerHTML = '<small class="vs-mut">Komentar gagal dimuat.</small>'; }
}
async function vsSendComment(id) {
    const inp = $id('vci_' + id); const text = inp ? inp.value.trim() : ''; if (!text) return;
    if (!VAUTH.user && !vsIsAdmin()) { alert('Masuk dulu untuk berkomentar.'); return; }
    const c = { type: 'versePost', itemId: String(id), name: (vsMyName() || 'Penggemar').slice(0, 60), text: text.slice(0, 500), ts: Date.now() };
    if (VAUTH.user) c.uid = VAUTH.user.uid;
    const av = vsMyAv(); if (av) c.av = av;
    try { await window.loreviaComments.add(c); const b = $id('vcm_' + id); b.hidden = true; vsComments(id); }
    catch (e) { alert('Komentar gagal dikirim: ' + vsAuthErr(e)); }
}
async function vsDelComment(pid, cid) { try { await window.loreviaComments.del(cid); const b = $id('vcm_' + pid); b.hidden = true; vsComments(pid); } catch (e) { alert('Gagal menghapus komentar.'); } }
function vsCarScroll(el) {
    const i = Math.round(el.scrollLeft / Math.max(1, el.clientWidth));
    const dots = el.nextElementSibling;
    if (dots && dots.classList.contains('vs-dots')) [...dots.children].forEach((d, k) => d.classList.toggle('on', k === i));
}
async function vsLike(id) {
    const p = vsFindPost(id); if (!p) return;
    p._liked = !p._liked; p.likes = Math.max(0, (p.likes || 0) + (p._liked ? 1 : -1));
    const pre = p.fan ? 'fp_' : 'vp_';
    try { const L = vsLikedSet(); if (p._liked) L[pre + id] = 1; else delete L[pre + id]; localStorage.setItem('lorevia_liked', JSON.stringify(L)); } catch (e) {}
    const btn = document.querySelector('#post_' + id + ' .vs-like');
    if (btn) { btn.classList.toggle('on', p._liked); btn.innerHTML = (p._liked ? VS_ICON.heart : VS_ICON.heartO) + '<span id="vsl_' + id + '">' + p.likes.toLocaleString('id-ID') + '</span>'; }
    if (window.uiSound) window.uiSound('pop');
    if (window.loreviaBump) window.loreviaBump(p.fan ? 'verseFanPosts' : 'versePosts', id, 'likes', p._liked ? 1 : -1);
}

async function vsPlayPost(id) {
    const p = (appData.versePosts || []).find(x => x.id === id); if (!p || !p.audio) return;
    try {
        const url = await mediaUrl(p.audio);
        const au = p.authorType === 'artist' ? vsArtist(p.authorId) : vsGroup(p.authorId);
        const el = new Audio(url);
        window.floatMusic(el, { title: p.audio.title || 'Musik', artist: au ? au.name : 'Lorevia Verse', cover: au && au.photo });
        el.play().catch(() => {});
    } catch (e) { alert('Gagal memutar musik: ' + (e.message || e)); }
}
async function vsDeletePost(id) {
    if (!confirm('Hapus postingan ini?')) return;
    const fp = (VSF.posts || []).findIndex(x => x.id === id);
    if (fp >= 0) {
        try { await window.loreviaDoc.del('verseFanPosts', id); VSF.posts.splice(fp, 1); renderView(); } catch (e) { alert('Gagal menghapus: ' + vsAuthErr(e)); }
        return;
    }
    const i = appData.versePosts.findIndex(x => x.id === id); if (i < 0) return;
    appData.versePosts.splice(i, 1);
    await commitAdminChange('Postingan dihapus.');
}

async function vsToggleExclusive(id) {
    const p = appData.versePosts.find(x => x.id === id); if (!p) return;
    if (p.exclusive) { p.exclusive = false; p.price = 0; }
    else {
        const v = parseInt(prompt('Harga konten eksklusif (Rp' + VS_MIN_PRICE + ' - Rp' + VS_MAX_PRICE + '):', '5000'), 10);
        if (!(v >= VS_MIN_PRICE && v <= VS_MAX_PRICE)) { alert('Harga harus antara Rp1.000 dan Rp10.000.'); return; }
        p.exclusive = true; p.price = v;
    }
    await commitAdminChange(p.exclusive ? 'Postingan dijadikan eksklusif.' : 'Postingan dijadikan publik.');
}

// ---------- Konten eksklusif: kode pembayaran ----------
function vsModal(html, cls) {
    let m = document.getElementById('vsModal');
    if (!m) { m = document.createElement('div'); m.id = 'vsModal'; m.addEventListener('click', e => { if (e.target === m) vsModalClose(); }); document.body.appendChild(m); }
    m.innerHTML = `<div class="vs-sheet vs-glass ${cls || ''}">${html}</div>`; m.classList.add('open');
}
function vsModalClose() { const m = document.getElementById('vsModal'); if (m) m.classList.remove('open'); }
function vsUnlockOpen(id) {
    const p = appData.versePosts.find(x => x.id === id); if (!p) return;
    vsModal(`<h3>Buka konten eksklusif</h3><p class="vs-mut">Harga ${vsRp(p.price)}. Buat kode pesanan, bayar sesuai arahan admin Lorevia, lalu masukkan kode setelah admin melunasi.</p>
        <div class="vs-form"><input id="ulName" placeholder="Nama kamu"><input id="ulContact" placeholder="Kontak (WhatsApp / Instagram)"><button type="button" class="vs-btn" onclick="vsUnlockCreate('${id}')">Buat kode pesanan</button></div>
        <hr><p class="vs-mut">Sudah punya kode yang sudah lunas?</p>
        <div class="vs-form"><input id="ulCode" placeholder="Masukkan kode" style="text-transform:uppercase"><button type="button" class="vs-btn ghost" onclick="vsUnlockCheck('${id}')">Buka dengan kode</button></div>
        <div id="ulMsg" class="vs-mut"></div>`);
}
async function vsUnlockCreate(id) {
    const name = document.getElementById('ulName').value.trim(), contact = document.getElementById('ulContact').value.trim();
    if (!name || !contact) { document.getElementById('ulMsg').textContent = 'Isi nama dan kontak dulu.'; return; }
    const code = Math.random().toString(36).slice(2, 8).toUpperCase();
    appData.verseUnlocks.push({ id: 'ul_' + Date.now().toString(36), postId: id, buyer: name, contact, code, status: 'pending', ts: Date.now() });
    saveAppData(); const ok = await window.loreviaDbFlush();
    document.getElementById('ulMsg').innerHTML = ok ? `Kode pesananmu: <b class="vs-code">${code}</b><br>Simpan kode ini, bayar sesuai arahan admin, lalu masukkan kode di atas setelah admin menandai lunas.` : 'Gagal menyimpan pesanan ke database. Coba lagi.';
}
async function vsUnlockCheck(id) {
    const code = document.getElementById('ulCode').value.trim().toUpperCase();
    const u = (appData.verseUnlocks || []).find(x => x.code === code && x.postId === id);
    const msg = document.getElementById('ulMsg');
    if (!u) { msg.textContent = 'Kode tidak ditemukan untuk konten ini.'; return; }
    if (u.status !== 'paid') { msg.textContent = 'Pembayaran belum dikonfirmasi admin.'; return; }
    const L = vsUnlockedList(); if (L.indexOf(id) < 0) L.push(id);
    try { localStorage.setItem('lorevia_vs_unlocked', JSON.stringify(L)); } catch (e) {}
    vsModalClose(); renderView();
}

// ---------- Story ----------
let vsStoryTimer = null;
function vsOpenStory(artistId, idx) {
    const list = vsStoriesOf(artistId); const a = vsArtist(artistId);
    if (!list.length) { vsOpenArtist(artistId); return; }
    idx = idx || 0;
    if (idx >= list.length) { vsCloseStory(); return; }
    let ov = document.getElementById('vsStory');
    if (!ov) { ov = document.createElement('div'); ov.id = 'vsStory'; document.body.appendChild(ov); }
    const s = list[idx];
    ov.innerHTML = `<div class="st-bars">${list.map((_, i) => `<i class="${i < idx ? 'done' : i === idx ? 'now' : ''}"><u></u></i>`).join('')}</div>
        <div class="st-head">${vsAv(a && a.photo, a && a.name, 'sm')}<b>${escHtml(a ? a.name : '')}</b><span>${vsAgo(s.ts)}</span><button type="button" onclick="vsCloseStory()">&times;</button></div>
        <div class="st-img"><img src="${escHtml(s.photo)}" alt=""></div>${s.text ? `<p class="st-cap">${escHtml(s.text)}</p>` : ''}
        <div class="st-tap l" onclick="vsOpenStory('${artistId}', ${Math.max(0, idx - 1)})"></div><div class="st-tap r" onclick="vsOpenStory('${artistId}', ${idx + 1})"></div>`;
    ov.classList.add('open'); clearTimeout(vsStoryTimer);
    vsStoryTimer = setTimeout(() => vsOpenStory(artistId, idx + 1), 5000);
}
function vsCloseStory() { clearTimeout(vsStoryTimer); const ov = document.getElementById('vsStory'); if (ov) ov.classList.remove('open'); }

// ---------- Penulis postingan (dipakai akun artis & dasbor admin untuk akun grup) ----------
function vsComposerHtml(authorType, authorId, groupId) {
    const prices = []; for (let v = VS_MIN_PRICE; v <= VS_MAX_PRICE; v += 1000) prices.push(v);
    return `<div class="vs-form vs-composer">
        <textarea id="vcText" rows="3" placeholder="Tulis sesuatu untuk fans..." oninput="VSC.text = this.value">${escHtml(VSC.text)}</textarea>
        <div class="vc-photos">${VSC.photos.map((p, i) => `<div class="vc-ph"><img src="${p.data}" alt=""><button type="button" onclick="vcRecrop(${i})" title="Atur potongan">&#9986;</button><button type="button" class="x" onclick="vcRemove(${i})">&times;</button></div>`).join('')}
            ${VSC.photos.length < VS_MAX_PHOTOS ? `<label class="vc-add">+<input type="file" accept="image/*" multiple hidden onchange="vcPick(this)"></label>` : ''}</div>
        <small class="vs-mut">${VSC.photos.length}/${VS_MAX_PHOTOS} foto · rasio 1:1, potongan bisa diatur</small>
        <input id="vcSpotify" placeholder="Link Spotify (opsional) mis. https://open.spotify.com/track/..." value="${escHtml(VSC.spotify)}" oninput="VSC.spotify = this.value">
        <label class="vc-check"><input type="checkbox" ${VSC.exclusive ? 'checked' : ''} onchange="VSC.exclusive = this.checked; vcKeep()"> Konten eksklusif (berbayar)</label>
        ${VSC.exclusive ? `<label class="vc-row"><span>Harga (maks Rp10.000)</span><select onchange="VSC.price = parseInt(this.value, 10)">${prices.map(v => `<option value="${v}" ${VSC.price === v ? 'selected' : ''}>${vsRp(v)}</option>`).join('')}</select></label>` : ''}
        <button type="button" class="vs-btn" onclick="vcSubmit('${authorType}', '${authorId}', '${groupId || ''}')" ${VSC.busy ? 'disabled' : ''}>${VSC.busy || 'Terbitkan'}</button></div>`;
}
function vcKeep() { renderView(); }
async function vcPick(input) {
    const files = [...input.files]; input.value = '';
    for (const f of files) {
        if (VSC.photos.length >= VS_MAX_PHOTOS) break;
        const d = await openCropper(f);
        if (d) VSC.photos.push({ data: d, file: f });
    }
    renderView();
}
async function vcRecrop(i) { const p = VSC.photos[i]; if (!p) return; const d = await openCropper(p.file); if (d) { p.data = d; renderView(); } }
function vcRemove(i) { VSC.photos.splice(i, 1); renderView(); }
async function vcSubmit(authorType, authorId, groupId) {
    try {
        const text = (document.getElementById('vcText') ? document.getElementById('vcText').value : VSC.text).trim();
        const spRaw = (document.getElementById('vcSpotify') ? document.getElementById('vcSpotify').value : VSC.spotify).trim();
        const spotify = spRaw ? vsSpotify(spRaw) : null;
        if (spRaw && !spotify) { alert('Link Spotify tidak dikenali. Salin link lengkap dari Spotify (open.spotify.com/track/...).'); return; }
        if (!text && !VSC.photos.length && !spotify) { alert('Isi postingan dulu: teks, foto, atau link Spotify.'); return; }
        if (VSC.exclusive && !(VSC.price >= VS_MIN_PRICE && VSC.price <= VS_MAX_PRICE)) { alert('Harga eksklusif harus Rp1.000 - Rp10.000.'); return; }
        appData.versePosts.unshift({ id: 'vp_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5), authorType, authorId, groupId: groupId || '', text,
            photos: VSC.photos.map(p => p.data), exclusive: !!VSC.exclusive, price: VSC.exclusive ? VSC.price : 0, ts: Date.now(), likes: 0 });
        { const np = appData.versePosts[0]; if (spotify) { const c = VS_SPC[spotify.type + '_' + spotify.id] || {}; np.spotify = Object.assign({}, spotify); ['title', 'artist', 'cover'].forEach(k => { if (c[k]) np.spotify[k] = c[k]; }); } }
        if (spotify) VS.autoPid = appData.versePosts[0].id;
        VSC.text = ''; VSC.photos = []; VSC.spotify = ''; VSC.exclusive = false;
        await commitAdminChange('Postingan terbit!');
    } catch (err) { adminActionFailed(err); }
}

// ---------- Produk (album & merchandise) ----------
async function vsAddProduct(groupId, prefix) {
    prefix = prefix || 'vp';
    try {
        const g = id => document.getElementById(prefix + '_' + id);
        const name = g('name').value.trim(), price = parseInt(g('price').value, 10) || 0, qty = parseInt(g('qty').value, 10) || 0;
        const kind = g('kind').value, description = g('desc').value.trim(), files = [...(g('photo').files || [])].slice(0, 3);
        if (!name || price <= 0) { alert('Nama dan harga produk wajib diisi.'); return; }
        const images = [];
        for (const f of files) { const d = await openCropper(f); if (d) images.push(d); }
        appData.products.push({ id: Date.now(), name, description, price, qty, images, groupId, kind });
        await commitAdminChange('Produk ditambahkan ke store grup!');
    } catch (err) { adminActionFailed(err); }
}
async function vsDeleteProduct(id) {
    if (!confirm('Hapus produk ini?')) return;
    const i = appData.products.findIndex(p => p.id === id); if (i < 0) return;
    appData.products.splice(i, 1); await commitAdminChange('Produk dihapus.');
}
function vsProductFormHtml(groupId, prefix) {
    return `<div class="vs-form"><div class="vc-2"><input id="${prefix}_name" placeholder="Nama produk (mis. Album Vol.1 / Hoodie)"><select id="${prefix}_kind"><option value="album">Album</option><option value="merch">Merch / Aksesoris</option></select></div>
        <div class="vc-2"><input id="${prefix}_price" type="number" min="1000" placeholder="Harga (Rp)"><input id="${prefix}_qty" type="number" min="0" placeholder="Stok"></div>
        <textarea id="${prefix}_desc" rows="2" placeholder="Deskripsi singkat"></textarea>
        <label class="vc-row"><span>Foto produk (maks 3, dipotong 1:1)</span><input type="file" id="${prefix}_photo" accept="image/*" multiple></label>
        <button type="button" class="vs-btn" onclick="vsAddProduct(${groupId}, '${prefix}')">Tambah produk</button></div>`;
}
function vsStoreGrid(products, withOwner) {
    if (!products.length) return `<p class="vs-empty">Belum ada produk.</p>`;
    return `<div class="vs-grid">${products.map(p => {
        const idx = appData.products.indexOf(p);
        const stock = parseInt(p.qty, 10) || 0;
        return `<div class="vs-prod vs-glass"><div class="vs-pimg">${(p.images && p.images[0]) ? `<img src="${escHtml(p.images[0])}" alt="${escHtml(p.name)}" loading="lazy">` : '<span></span>'}<em>${p.kind === 'album' ? 'Album' : 'Merch'}</em></div>
            <b>${escHtml(p.name)}</b><span class="vs-price">${vsRp(p.price)}</span><small class="vs-mut">${stock > 0 ? 'Stok ' + stock : 'Habis'}</small>
            <input type="hidden" id="prodQty_${idx}" value="1">
            <button type="button" class="vs-btn sm" ${stock > 0 ? '' : 'disabled'} onclick="addToCart(${idx})">Masukkan keranjang</button>
            ${withOwner ? `<button type="button" class="vs-link" onclick="vsDeleteProduct(${p.id})">Hapus</button>` : ''}</div>`;
    }).join('')}</div>`;
}

// ---------- Navigasi dalam Verse ----------
function vsScrollTop() { const m = document.querySelector('.vs'); if (m) m.scrollTop = 0; }
function vsTab(t) { VS.tab = t; VS.artistId = null; vsDrawerClose(); renderView(); vsScrollTop(); }
function vsOpenGroup(id) { VS.groupId = id; VS.artistId = null; VS.tab = 'community'; renderView(); vsScrollTop(); }
function vsOpenArtist(id) { VS.artistId = id; VS.sub = 'posts'; renderView(); vsScrollTop(); }
function vsBackArtist() { VS.artistId = null; renderView(); }
function vsSub(s) { VS.sub = s; renderView(); }
function vsFeed(f) { VS.feed = f; renderView(); }
function vsArtistCircle(a) {
    const has = vsStoriesOf(a.id).length > 0;
    return `<button type="button" class="vs-circle ${has ? 'story' : ''}" onclick="${has ? `vsOpenStory('${a.id}')` : `vsOpenArtist('${a.id}')`}">${vsAv(a.photo, a.name, 'lg')}<span>${escHtml(a.name)}</span></button>`;
}

function vsGroupBySlug(slug) { return (appData.verseGroups || []).find(g => vsSlug(g.slug || g.name) === slug) || null; }

async function vsAddStory() {
    const me = vsSession(); if (!me) return;
    const f = document.getElementById('vsStoryFile').files[0]; if (!f) { alert('Pilih foto story dulu.'); return; }
    try {
        const d = await openCropper(f); if (!d) return;
        const cut = Date.now() - 86400000;
        appData.verseStories = appData.verseStories.filter(s => !(s.artistId === me.id && (s.ts || 0) <= cut));
        appData.verseStories.push({ id: 'vs_' + Date.now().toString(36), artistId: me.id, groupId: me.groupId || '', photo: d, text: (document.getElementById('vsStoryCap').value || '').trim(), ts: Date.now() });
        await commitAdminChange('Story terbit! Aktif selama 24 jam.');
    } catch (err) { adminActionFailed(err); }
}

// ---------- Tampilan ----------

// ---------- Profil (artis / grup / pengguna) ----------
function vsStaffPanel(kind, o) {
    const isA = kind === 'artist', tab = VS.stab || 'sum';
    const mine = (appData.versePosts || []).filter(p => p.authorType === kind && p.authorId === o.id).sort((a, b) => b.ts - a.ts);
    const likes = mine.reduce((a, p) => a + (p.likes || 0), 0), stories = isA ? vsStoriesOf(o.id).length : 0;
    vsLoadLetters();
    const letters = VSL.inbox === null ? '…' : VSL.inbox.length;
    const t = (k, l) => `<button type="button" class="${tab === k ? 'on' : ''}" onclick="VS.stab='${k}'; renderView()">${l}</button>`;
    const head = `<section class="vs-card vs-glass vs-staffhead"><div class="vs-me">${vsAv(o.photo, o.name, 'lg', isA ? vsArtistLv(o.id) : 0)}<div><b>${escHtml(o.name)}${VS_VF}</b><span class="vs-mut">${isA ? escHtml((vsGroup(o.groupId) || {}).name || '') + (o.emailHint ? ' · login ' + escHtml(o.emailHint) : '') : 'Akun grup resmi'}</span></div><button type="button" class="vs-link" onclick="vsLogout()">Keluar</button></div>
        <div class="vs-kpis"><div><b>${mine.length}</b><span>Postingan</span></div><div><b>${likes.toLocaleString('id-ID')}</b><span>Suka</span></div>${isA ? `<div><b>${stories}</b><span>Story aktif</span></div>` : ''}<div><b>${letters}</b><span>Surat masuk</span></div>${isA ? `<div><b>${(VSB.byArtist[o.id] || {}).active || 0}</b><span>Pelanggan</span></div>` : ''}</div></section>
        <div class="vs-ptabs vs-stabs">${t('sum', 'Ringkasan')}${t('post', 'Postingan')}${isA ? t('story', 'Story') + t('chat', 'Chat') : ''}${t('letter', 'Surat')}${t('profile', 'Profil')}${t('sec', 'Akun')}</div>`;
    let body = '';
    if (tab === 'post') body = `<section class="vs-card vs-glass"><h4>Postingan baru</h4><p class="vs-mut">Teks, sampai ${VS_MAX_PHOTOS} foto, link Spotify (judul, artis &amp; cover terdeteksi otomatis), dan konten eksklusif.</p>${vsComposerHtml(kind, o.id, isA ? o.groupId : o.id)}</section>
        <h4 class="vs-h">Postingan ${isA ? 'saya' : 'grup'}</h4>${mine.length ? mine.map(vsPostHtml).join('') : '<p class="vs-empty">Belum ada postingan.</p>'}`;
    else if (tab === 'story' && isA) {
        const ss = (appData.verseStories || []).filter(s => s.artistId === o.id).sort((a, b) => b.ts - a.ts);
        body = `<section class="vs-card vs-glass"><h4>Story (24 jam)</h4><div class="vs-form"><input type="file" id="vsStoryFile" accept="image/*"><input id="vsStoryCap" placeholder="Keterangan (opsional)"><button type="button" class="vs-btn" onclick="vsAddStory()">Pasang story</button></div></section>
        ${ss.length ? `<div class="vs-pgrid st">${ss.map(s => `<span><img src="${escHtml(s.photo)}" alt=""><button type="button" class="x" onclick="vsDelStory('${s.id}')">&times;</button><small>${vsAgo(s.ts)}</small></span>`).join('')}</div>` : '<p class="vs-empty">Belum ada story.</p>'}`;
    }
    else if (tab === 'chat' && isA) body = vsInboxHtml(o);
    else if (tab === 'letter') body = `<h4 class="vs-h">Surat dari penggemar</h4>${VSL.inbox === null ? '<p class="vs-empty">Memuat…</p>' : VSL.inbox.length ? VSL.inbox.map(l => vsLetterRow(l, true)).join('') : '<p class="vs-empty">Belum ada surat masuk.</p>'}`;
    else if (tab === 'profile') body = `<section class="vs-card vs-glass"><h4>Edit profil</h4>${vsProfileFormHtml(kind, o)}</section>`;
    else if (tab === 'sec') body = `<section class="vs-card vs-glass"><h4>Akun &amp; keamanan</h4><p class="vs-mut" style="line-height:1.6">${isA ? 'Kamu masuk sebagai <b>' + escHtml(o.emailHint || '') + '</b>.' : 'Akun grup masuk lewat Google: <b>' + escHtml((VAUTH.user || {}).email ? vsMaskEmail(VAUTH.user.email) : '') + '</b>.'}</p>
        ${isA && VAUTH.user && String(VAUTH.user.email).endsWith('@' + window.LV_ARTIST_DOMAIN) ? '<button type="button" class="vs-btn" onclick="vsChangeArtistPw()">Ganti sandi</button>' : ''}
        <button type="button" class="vs-btn ghost" style="margin-top:8px" onclick="vsLogout()">Keluar</button></section>`;
    else body = `<section class="vs-card vs-glass"><h4>Aksi cepat</h4><div class="vs-quick"><button type="button" class="vs-glass" onclick="VS.stab='post'; renderView()"><span>${VS_ICON.plus.replace('width="28" height="28"', 'width="22" height="22"')}</span><b>Posting</b></button>
        ${isA ? `<button type="button" class="vs-glass" onclick="VS.stab='story'; renderView()"><span>${VS_ICON.cam}</span><b>Story</b></button>` : ''}<button type="button" class="vs-glass" onclick="VS.stab='letter'; renderView()"><span>${VS_ICON.mail}</span><b>Surat</b></button></div></section>
        <h4 class="vs-h">Postingan terbaru</h4>${mine.length ? mine.slice(0, 3).map(vsPostHtml).join('') : '<p class="vs-empty">Belum ada postingan. Buka tab Postingan untuk menulis.</p>'}`;
    return head + body;
}
function vsPanelHtml(me) { return vsStaffPanel('artist', me); }
function vsGroupPanelHtml(g) { return vsStaffPanel('group', g); }
async function vsDelStory(id) { if (!confirm('Hapus story ini?')) return; appData.verseStories = (appData.verseStories || []).filter(s => s.id !== id); await commitAdminChange('Story dihapus.'); }
function vsProfileFormHtml(kind, o) {
    return `<div class="vs-form"><div class="vc-ph" style="width:72px;height:72px">${vsAv(o.photo, o.name, 'lg')}</div>
        <label class="vc-row"><span>Ganti foto profil (dipotong 1:1)</span><input type="file" id="vpfPhoto" accept="image/*"></label>
        <input id="vpfName" maxlength="100" placeholder="Nama" value="${escHtml(o.name)}">
        <textarea id="vpfBio" rows="2" maxlength="500" placeholder="Bio singkat">${escHtml(o.bio || '')}</textarea>
        <button type="button" class="vs-btn" onclick="vsSaveProfile('${kind}', '${o.id}')">Simpan profil</button><div id="vpfMsg" class="vs-mut"></div></div>`;
}
async function vsSaveProfile(kind, id) {
    const o = kind === 'artist' ? vsArtist(id) : vsGroup(id); if (!o) return;
    const msg = document.getElementById('vpfMsg');
    try {
        const name = document.getElementById('vpfName').value.trim(), bio = document.getElementById('vpfBio').value.trim();
        if (!name) { msg.textContent = 'Nama tidak boleh kosong.'; return; }
        const f = document.getElementById('vpfPhoto').files[0];
        if (f) { const d = await openCropper(f); if (d) o.photo = d; }
        o.name = name; o.bio = bio;
        await commitAdminChange('Profil diperbarui!');
    } catch (err) { adminActionFailed(err); }
}

// ---------- Sheet postingan penggemar: teks, foto, musik Spotify (deteksi judul & artis) ----------
function vsOpenCompose() {
    if (vsSession() || vsGroupSession()) { vsTab('me'); setTimeout(() => { const t = $id('vcText'); if (t) { t.scrollIntoView({ block: 'center' }); t.focus(); } }, 80); return; }
    if (!VAUTH.user) { alert(vsIsAdmin() ? 'Postingan penggemar memakai akun Google. Admin membuat postingan grup lewat Dasbor Admin.' : 'Masuk dengan Google dulu untuk memposting.'); return; }
    vsComposeRender();
}
function vsSpFormHtml() {
    const s = VSP.sp;
    if (!VSP.url.trim()) return '<small class="vs-mut">Tempel link lagu/album/playlist dari Spotify. Judul lagu dan pencipta/artis dideteksi otomatis.</small>';
    if (!s) return '<div class="vs-note">Link Spotify tidak dikenali. Salin link lengkap (open.spotify.com/track/…).</div>';
    const st = VSP.spState === 'loading' ? 'Mendeteksi judul & artis…' : VSP.spState === 'ok' ? '✓ Terdeteksi otomatis. Boleh kamu ubah.' : 'Tidak terdeteksi otomatis. Isi judul & artis di bawah.';
    return `<div class="vs-spcard"><span class="vs-spc lg">${s.cover ? `<img src="${escHtml(s.cover)}" alt="">` : VS_ICON.note}</span>
        <div class="vs-form"><input id="vpTitle" maxlength="200" placeholder="Judul lagu" value="${escHtml(s.title || '')}" oninput="VSP.sp.title=this.value"><input id="vpArtist" maxlength="200" placeholder="Pencipta / artis" value="${escHtml(s.artist || '')}" oninput="VSP.sp.artist=this.value"></div></div><small class="vs-mut">${st}</small>`;
}
function vsSpUpdate() { const el = $id('vpSp'); if (el) el.innerHTML = vsSpFormHtml(); }
let vsSpTimer = null;
function vsSpInput(v) {
    VSP.url = v; clearTimeout(vsSpTimer);
    vsSpTimer = setTimeout(() => {
        const p = vsSpotify(v);
        if (!p) { VSP.sp = null; VSP.spState = ''; vsSpUpdate(); return; }
        if (!VSP.sp || VSP.sp.id !== p.id) VSP.sp = Object.assign({ title: '', artist: '', cover: '' }, p);
        VSP.spState = 'loading'; vsSpUpdate();
        vsSpMeta(p).then(m => {
            if (!VSP.sp || VSP.sp.id !== p.id) return;
            if (m.title && !VSP.sp.title) VSP.sp.title = m.title; if (m.artist && !VSP.sp.artist) VSP.sp.artist = m.artist; if (m.cover) VSP.sp.cover = m.cover;
            VSP.spState = (m.title || m.artist) ? 'ok' : 'manual'; vsSpUpdate();
        });
    }, 450);
}
async function vpPick(input) {
    const files = [...input.files]; input.value = '';
    for (const f of files) {
        if (VSP.photos.length >= VS_FAN_PHOTOS) break;
        try { const d = await openCropper(f); if (d) VSP.photos.push(await vsShrink(d, 720, 720, .78)); } catch (e) { alert('Foto tidak bisa diproses.'); }
    }
    vsComposeRender();
}
function vpRemove(i) { VSP.photos.splice(i, 1); vsComposeRender(); }

// ---------- Edit profil penggemar (foto, sampul, nama, bio) ----------
function vsEditProfile() {
    if (!VAUTH.user) return;
    VSE.photo = ''; VSE.av = ''; VSE.cover = '';
    const p = vsProf();
    vsModal(`<h3>Edit profil</h3><div class="vs-form">
        <div class="vs-ep-cover" id="vepCover" ${p.cover ? `style="background-image:url('${escHtml(p.cover)}')"` : ''}><label class="vs-ep-btn">${VS_ICON.cam}<span>Ganti sampul</span><input type="file" accept="image/*" hidden onchange="vepCover(this)"></label></div>
        <div class="vs-ep-av"><span id="vepAv">${vsAv(vsMyPhoto(), vsFanName(), 'xl')}</span><label class="vs-ep-btn sm">${VS_ICON.cam}<span>Ganti foto profil</span><input type="file" accept="image/*" hidden onchange="vepPhoto(this)"></label></div>
        ${p.username ? `<small class="vs-mut">Username: <b>@${escHtml(p.username)}</b> (tidak bisa diubah)</small>` : ''}
        <input id="vepNick" maxlength="40" placeholder="Nama panggilan" value="${escHtml(p.nickname || vsFanName())}">
        <textarea id="vepBio" rows="3" maxlength="300" placeholder="Bio singkat">${escHtml(p.bio || '')}</textarea>
        ${p.ph ? `<input id="vepPw" type="password" autocomplete="current-password" placeholder="Sandi akun (konfirmasi)"><button type="button" class="vs-link" style="align-self:flex-start" onclick="vsResetPwSheet()">Lupa sandi?</button>` : ''}
        <div id="vepMsg" class="vs-note" hidden></div>
        <button type="button" class="vs-btn" id="vepGo" onclick="vsSaveFanProfile()">Simpan profil</button><button type="button" class="vs-link" onclick="vsModalClose()" style="align-self:center">Batal</button></div>`);
}
async function vsSaveFanProfile() {
    const nick = ($id('vepNick').value || '').trim().slice(0, 40), bio = ($id('vepBio').value || '').trim().slice(0, 300), msg = $id('vepMsg'), p = vsProf();
    const fail = t => { msg.hidden = false; msg.textContent = t; const go = $id('vepGo'); go.disabled = false; go.textContent = 'Simpan profil'; };
    if (!nick) return fail('Nama panggilan tidak boleh kosong.');
    const go = $id('vepGo'); go.disabled = true; go.textContent = 'Menyimpan…'; msg.hidden = true;
    try {
        if (p.ph) { const ok = (await vsHashPw($id('vepPw').value || '', p.ps)) === p.ph; if (!ok) return fail('Sandi akun salah.'); }
        const patch = { nickname: nick, bio };
        if (VSE.photo) { patch.photo = VSE.photo; patch.av = VSE.av; }
        if (VSE.cover) patch.cover = VSE.cover;
        await vsSaveProf(patch);
        const chk = await window.loreviaDoc.get('verseProfiles', VAUTH.user.uid);   // pastikan benar-benar tersimpan di database
        if (!chk || chk.nickname !== nick) throw new Error('Data tidak tersimpan di server. Periksa Rules Firestore.');
        vsModalClose(); renderView();
    } catch (e) { fail('Profil gagal disimpan: ' + vsAuthErr(e)); }
}
async function vepPhoto(inp) {
    const f = inp.files[0]; inp.value = ''; if (!f) return;
    try { const d = await openCropper(f); if (!d) return; VSE.photo = await vsShrink(d, 256, 256, .82); VSE.av = await vsShrink(d, 64, 64, .7); $id('vepAv').innerHTML = vsAv(VSE.photo, vsFanName(), 'xl'); }
    catch (e) { alert('Foto tidak bisa diproses.'); }
}
async function vepCover(inp) {
    const f = inp.files[0]; inp.value = ''; if (!f) return;
    try { VSE.cover = await vsShrink(await vsReadFile(f), 900, 360, .72); $id('vepCover').style.backgroundImage = "url('" + VSE.cover + "')"; }
    catch (e) { alert('Gambar tidak bisa diproses.'); }
}
function vsFollowSheet() {
    const all = (appData.verseGroups || []).map(g => ({ id: g.id, name: g.name, photo: g.photo, sub: 'Komunitas' })).concat((appData.verseArtists || []).map(a => ({ id: a.id, name: a.name, photo: a.photo, sub: (vsGroup(a.groupId) || {}).name || 'Artis' })));
    vsModal(`<h3>Mengikuti (${vsFollowCount()})</h3><p class="vs-mut">Semua komunitas &amp; artis otomatis kamu ikuti saat mendaftar.</p>
        <div class="vs-flist">${all.map(x => `<div class="vs-frow">${vsAv(x.photo, x.name, 'sm')}<div><b>${escHtml(x.name)}</b><small>${escHtml(x.sub)}</small></div>${vsFollowBtn(x.id)}</div>`).join('') || '<p class="vs-empty">Belum ada.</p>'}</div>`);
}


