function vsAudNext(d, auto) {
    const l = vsAudios(); if (!l.length) return; const from = VSA.i < 0 ? VSA.sel : VSA.i; let n;
    if (auto && VSA.rep) n = from; else if (VSA.shuf && l.length > 1) { do { n = Math.floor(Math.random() * l.length); } while (n === from); } else n = (from + d + l.length) % l.length;
    if (n === from && VSA.el) { VSA.el.currentTime = 0; VSA.el.play().catch(() => {}); } else vsAudPlay(n);
}
function vsToggle(k) { VSA[k] = !VSA[k]; if (k === 'rep' && VSA.el) VSA.el.loop = false; document.querySelectorAll('[data-t="' + k + '"]').forEach(b => b.classList.toggle('on', VSA[k])); }
// ---------- Beranda & Chat bergaya baru ----------
function vsHelloHtml() {
    const nm = VAUTH.user ? vsFanName() : 'Tamu';
    return `<div class="vs-hello"><div class="vs-hello-r"><span class="vs-hello-av">${vsAv(vsMyPhoto(), nm, 'sm')}</span><button type="button" class="vs-round bub" onclick="vsTab('artists')" aria-label="Cari">${VS_ICON.search}</button></div><h1>Jelajahi &amp; chat<br>dengan idolmu</h1><p>Halo, ${escHtml(nm)}</p></div>`;
}
function vsHomeHtml() {
    if (!(appData.verseGroups || []).length) return `<p class="vs-empty">Belum ada akun grup. Admin dapat menambahkannya di Dasbor Admin &rarr; Lorevia Verse.</p>`;
    const posts = vsFeedPosts(), nf = vsFollowCount();
    let empty = 'Belum ada postingan.';
    if (VS.feed === 'foryou' && !nf) empty = 'Kamu belum mengikuti siapa pun. Buka <b>Discover</b> lalu pilih artis atau grup favoritmu.';
    else if (VS.feed === 'foryou') empty = 'Belum ada postingan dari yang kamu ikuti. Lihat tab Terbaru.';
    return `${vsHelloHtml()}${vsAdHtml()}${vsQuick()}${vsStoryRow()}${vsBanners()}${vsFeedTabs()}${posts.length ? posts.map(vsPostHtml).join('') : `<div class="vs-empty">${empty}${VS.feed === 'foryou' && !nf ? '<br><button type="button" class="vs-btn" style="margin-top:10px" onclick="vsTab(\'artists\')">Cari artis &amp; grup</button>' : ''}</div>`}`;
}
function vsChatsHtml() {
    vsLoadSubs(); const arts = appData.verseArtists || [], mine = (VSB.mine || []).slice().sort((a, b) => b.end - a.end);
    const act = mine.filter(s => s.end > Date.now()).map(s => vsArtist(s.artistId)).filter(Boolean);
    const row = (a, s) => { const on = s && s.end > Date.now(); return `<div class="vs-cr ${on ? '' : 'lock'}" ${on ? `onclick="vsOpenChat('${a.id}')"` : ''}><span class="vs-cr-av">${vsAv(a.photo, a.name, 'sm', vsArtistLv(a.id))}${on ? '<i></i>' : ''}</span><div class="vs-cr-t"><b>${escHtml(a.name)}${VS_VF}</b><small>${on ? 'Aktif sampai ' + vsDate(s.end) : s ? 'Langganan berakhir ' + vsDate(s.end) : 'Wajib langganan untuk chat & call'}</small></div>
        ${on ? '<span class="vs-cr-b">Chat</span>' : `<button type="button" class="vs-btn sm" onclick="event.stopPropagation(); vsSubOpen('${a.id}')">${s ? 'Perpanjang' : 'Langganan'}</button>`}</div>`; };
    const others = arts.filter(a => !act.some(x => x.id === a.id));
    return `<div class="vs-chh"><h2>Chat</h2><span><button type="button" class="vs-round bub" onclick="vsTab('artists')" aria-label="Cari">${VS_ICON.search}</button><button type="button" class="vs-round bub" onclick="vsTab('home')" aria-label="Beranda">${VS_ICON.home}</button></span></div>
        ${vsLvLineHtml()}
        ${act.length ? `<div class="vs-row vs-cstrip">${act.map(a => `<button type="button" class="vs-circle" onclick="vsOpenChat('${a.id}')">${vsAv(a.photo, a.name, 'lg', vsArtistLv(a.id))}<span>${escHtml(a.name.split(' ')[0])}</span></button>`).join('')}</div>` : ''}
        <div class="vs-lock-note"><span>${VS_ICON.lock}</span><div><b>Chat &amp; call khusus pelanggan</b><small>${vsRp(VS_SUB_PRICE)} / ${VS_SUB_DAYS} hari per artis. Aktif otomatis setelah pembayaran terdeteksi.</small></div></div>
        <h4 class="vs-h">Pesan</h4>
        ${act.length ? mine.filter(s => s.end > Date.now()).map(s => row(vsArtist(s.artistId), s)).join('') : '<p class="vs-empty" style="padding:12px">Belum ada langganan aktif.</p>'}
        ${others.length ? `<h4 class="vs-h">Artis lain</h4>${others.map(a => row(a, mine.find(s => s.artistId === a.id) || null)).join('')}` : ''}`;
}

// =====================================================================
// V8 — Musik gaya "Listening now / Trending", chat bubble + keyboard HP, tema LinkedIn/Loop
// =====================================================================
function vsMode(m) { VSA.mode = m; renderView(); }
function vsToggle(k) { VSA[k] = !VSA[k]; if (k === 'rep' && VSA.el) VSA.el.loop = false; document.querySelectorAll('[data-t="' + k + '"]').forEach(b => b.classList.toggle('on', VSA[k])); }
function vsHist() { try { return JSON.parse(localStorage.getItem('lvHist') || '[]'); } catch (e) { return []; } }
function vsHistAdd(t) { try { const k = String(t.id || t.title); const h = vsHist().filter(x => x !== k); h.unshift(k); localStorage.setItem('lvHist', JSON.stringify(h.slice(0, 12))); } catch (e) {} }
function vsFavs() { try { return JSON.parse(localStorage.getItem('lvFav') || '[]'); } catch (e) { return []; } }
function vsTKey(t) { return String(t.id || t.title); }
function vsFavToggle(i) {
    const t = vsAudios()[i]; if (!t) return; const k = vsTKey(t); let f = vsFavs(); f = f.includes(k) ? f.filter(x => x !== k) : f.concat(k);
    try { localStorage.setItem('lvFav', JSON.stringify(f)); } catch (e) {}
    document.querySelectorAll('[data-fav]').forEach(b => b.classList.toggle('on', f.includes(vsTKey(vsAudios()[VSA.i >= 0 ? VSA.i : VSA.sel] || {}))));
}
function vsShareTrack() {
    const t = vsAudios()[VSA.i >= 0 ? VSA.i : VSA.sel]; if (!t) return; const txt = (t.title || 'Lagu') + ' — ' + (t.artist || 'Lorevia Music');
    if (navigator.share) navigator.share({ title: txt, url: location.href.split('#')[0] }).catch(() => {}); else { try { navigator.clipboard.writeText(txt + ' ' + location.href.split('#')[0]); alert('Tautan disalin'); } catch (e) {} }
}
function vsPlayOpen(i) { VSA.mode = 'now'; VSA.sel = i; if (VSA.i === i) { renderView(); return; } vsAudPlay(i); const l = vsAudios(); if (l[i]) vsHistAdd(l[i]); renderView(); }
function vsMiniHtml() {
    const t = vsAudios()[VSA.i]; if (!t) return '';
    return `<div class="vs-mini" data-aud="root"><button type="button" class="vs-mini-in" onclick="vsMode('now'); vsTab('music')"><span class="vs-mini-art">${t.cover ? `<img src="${escHtml(t.cover)}" alt="">` : VS_ICON.note}</span><span class="vs-mini-t"><b data-aud="title">${escHtml(t.title || 'Tanpa judul')}</b><small data-aud="artist">${escHtml(t.artist || 'Lorevia Music')}</small></span></button>
        <button type="button" class="vs-mini-b" onclick="vsAudPlay(${VSA.i})" aria-label="Putar/jeda"><svg class="pl" viewBox="0 0 24 24" width="22" height="22"><path fill="currentColor" d="M8 5v14l11-7z"/></svg><svg class="pa" viewBox="0 0 24 24" width="22" height="22"><path fill="currentColor" d="M6 5h4v14H6zM14 5h4v14h-4z"/></svg></button>
        <button type="button" class="vs-mini-b" onclick="vsAudNext(1)" aria-label="Berikutnya"><svg viewBox="0 0 24 24" width="20" height="20"><path fill="currentColor" d="M6 6l9 6-9 6zM17 6h2v12h-2z"/></svg></button><i class="vs-mini-bar" data-aud="bar"></i></div>`;
}
function vsMusicHtml() {
    const l = vsAudios();
    if (!l.length) return vsSubHead('Lorevia Music', "vsTab('home')") + '<p class="vs-empty">Belum ada musik. Admin dapat mengunggah audio di Dasbor Admin &rarr; Audio Playlist.</p>';
    if (VSA.sel >= l.length) VSA.sel = 0;
    const cov = t => t.cover ? `<img src="${escHtml(t.cover)}" alt="" loading="lazy">` : `<em>${VS_ICON.note}</em>`;
    const ic = (p, w) => `<svg viewBox="0 0 24 24" width="${w || 24}" height="${w || 24}"><path fill="currentColor" d="${p}"/></svg>`;
    const PL = '<svg class="pl" viewBox="0 0 24 24" width="28" height="28"><path fill="currentColor" d="M8 5v14l11-7z"/></svg><svg class="pa" viewBox="0 0 24 24" width="28" height="28"><path fill="currentColor" d="M6 5h4v14H6zM14 5h4v14h-4z"/></svg>';
    if (VSA.mode === 'now') {
        const i = VSA.i >= 0 ? VSA.i : VSA.sel, t = l[i] || l[0], nx = l[(i + 1) % l.length], fav = vsFavs().includes(vsTKey(t));
        setTimeout(vsAudSync, 20);
        return `<div class="vs-ln" data-aud="root"><div class="vs-ln-h"><button type="button" class="vs-round bub" onclick="vsMode('home')" aria-label="Kembali">${VS_ICON.back}</button><b>Listening now</b><span></span></div>
          <div class="vs-ln-art"><svg class="vs-ring" viewBox="0 0 100 100" preserveAspectRatio="none"><rect class="bg" x="2" y="2" width="96" height="96" rx="22" pathLength="100"/><rect class="fg" data-aud="ring" x="2" y="2" width="96" height="96" rx="22" pathLength="100"/></svg><span class="vs-ln-c">${cov(t)}</span></div>
          <div class="vs-ln-t"><div><h3 data-aud="title">${escHtml(t.title || 'Tanpa judul')}</h3><p data-aud="artist">${escHtml(t.artist || 'Lorevia Music')}</p></div>
            <span><button type="button" data-fav class="vs-ib ${fav ? 'on' : ''}" onclick="vsFavToggle(${i})" aria-label="Suka">${VS_ICON.heart}</button><button type="button" class="vs-ib" onclick="vsShareTrack()" aria-label="Bagikan">${ic('M18 16a3 3 0 0 0-2.200 1L9 13.700a3 3 0 0 0 0-3.400L15.800 7A3 3 0 1 0 15 5a3 3 0 0 0 .1.800L8.200 9A3 3 0 1 0 8.200 15l6.900 3.300A3 3 0 1 0 18 16z', 20)}</button></span></div>
          <div class="vs-wave" data-aud="bar" onclick="vsAudSeek(event,this)"><div class="bg">${vsWave(t.title)}</div><div class="fg">${vsWave(t.title)}</div></div>
          <div class="vs-prog"><span data-aud="cur">0:00</span><span data-aud="dur">0:00</span></div>
          <div class="vs-ctl"><button type="button" data-t="shuf" class="sm ${VSA.shuf ? 'on' : ''}" onclick="vsToggle('shuf')" aria-label="Acak">${ic('M17 3h4v4h-2V6.400l-4.200 4.200-1.400-1.400L17.600 5H17zM3 5h4.500l9 11H21v2h-5.500L6.500 7H3zM3 17h3.500l2.300-2.800 1.300 1.600L7.600 19H3z', 22)}</button>
            <button type="button" onclick="vsAudNext(-1)" aria-label="Sebelumnya">${ic('M18 6l-9 6 9 6zM5 6h2v12H5z')}</button>
            <button type="button" class="big" onclick="vsAudPlay(${i})" aria-label="Putar/jeda">${PL}</button>
            <button type="button" onclick="vsAudNext(1)" aria-label="Berikutnya">${ic('M6 6l9 6-9 6zM17 6h2v12h-2z')}</button>
            <button type="button" data-t="rep" class="sm ${VSA.rep ? 'on' : ''}" onclick="vsToggle('rep')" aria-label="Ulang">${ic('M7 7h10v3l4-4-4-4v3H5v6h2zm10 10H7v-3l-4 4 4 4v-3h12v-6h-2z', 22)}</button></div>
          <div class="vs-nu"><small>Next up</small><button type="button" onclick="vsPlayOpen(${(i + 1) % l.length})"><span class="vs-nu-c">${cov(nx)}</span><span><b>${escHtml(nx.title || 'Tanpa judul')}</b><small>${escHtml(nx.artist || 'Lorevia Music')}</small></span>${VS_ICON.chev}</button></div></div>`;
    }
    const nm = VAUTH.user ? vsFanName() : 'Tamu', hist = vsHist();
    let rec = hist.map(k => l.findIndex(t => vsTKey(t) === k)).filter(x => x >= 0); l.forEach((_, i) => { if (!rec.includes(i)) rec.push(i); }); rec = rec.slice(0, 4);
    const trend = l.map((t, i) => i).sort((a, b) => ((l[b].plays || 0) - (l[a].plays || 0)) || (a - b)).slice(0, 8);
    const week = l.slice(0, 12);
    return `<div class="vs-mh"><div class="vs-mh-top"><div><h1>Hi, ${escHtml(nm)}!</h1><p>Let's listen to something cool today</p></div><button type="button" class="vs-round bub" onclick="vsTab('home')" aria-label="Beranda">${VS_ICON.back}</button></div>
      <label class="vs-ms"><svg viewBox="0 0 24 24" width="18" height="18"><path fill="none" stroke="currentColor" stroke-width="2.200" stroke-linecap="round" d="M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zm9 16-4-4"/></svg><input type="search" placeholder="Cari lagu atau artis" oninput="vsSongFilter(this.value)"></label>
      <h4 class="vs-mh-h">Recently played</h4>
      <div class="vs-rec">${rec.map(i => `<button type="button" class="vs-rc ${i === VSA.i ? 'on' : ''}" onclick="vsPlayOpen(${i})"><span class="vs-rc-c">${cov(l[i])}</span><b>${escHtml(l[i].title || 'Tanpa judul')}</b></button>`).join('')}</div>
      <h4 class="vs-mh-h">Trending now</h4>
      <div class="vs-trend">${trend.map(i => `<button type="button" class="vs-tc ${i === VSA.i ? 'on' : ''}" onclick="vsPlayOpen(${i})"><span class="vs-tc-c">${cov(l[i])}<u>${ic('M8 5v14l11-7z', 22)}</u></span><b>${escHtml(l[i].title || 'Tanpa judul')}</b><small>${escHtml(l[i].artist || 'Lorevia Music')}</small></button>`).join('')}</div>
      <h4 class="vs-mh-h">Songs of the week</h4>
      <div class="vs-sw" id="vsSw">${week.map((t, i) => `<button type="button" class="vs-sr ${i === VSA.i ? 'on' : ''}" data-q="${escHtml(((t.title || '') + ' ' + (t.artist || '')).toLowerCase())}" onclick="vsPlayOpen(${i})"><span class="vs-sr-c">${cov(t)}</span><span class="vs-sr-t"><b>${escHtml(t.title || 'Tanpa judul')}</b><small>${escHtml(t.artist || 'Lorevia Music')}</small>${i === VSA.i ? '<i class="vs-sr-bar" data-aud="bar"></i>' : ''}</span><span class="vs-sr-p">${i === VSA.i ? '<i class="vs-eqm"><u></u><u></u><u></u></i>' : ic('M8 5v14l11-7z', 18)}</span></button>`).join('')}</div></div>`;
}
function vsSongFilter(q) { q = String(q || '').toLowerCase().trim(); document.querySelectorAll('#vsSw .vs-sr').forEach(b => { b.style.display = !q || b.dataset.q.includes(q) ? '' : 'none'; }); }
// ---------- Chat bubble ----------
function vsMsgHtml(m) {
    const staff = !!vsSession(), mine = staff ? m.role === 'artist' : m.role === 'fan', a = vsArtist(VSM.aid) || {};
    const who = m.role === 'artist' ? vsAv(a.photo, a.name, 'sm') : vsAv('', m.name || 'F', 'sm');
    const tm = new Date(m.ts).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    return `<div class="vs-msg ${mine ? 'me' : ''}">${mine ? '' : `<span class="vs-mav">${who}</span>`}<div class="vs-mb"><div class="vs-bub">${escHtml(m.text)}</div><small>${tm}</small></div></div>`;
}
function vsChatHtml() {
    const a = vsArtist(VSM.aid), staff = vsSession(); if (!a) return vsChatsHtml();
    const on = staff || vsSubActive(a.id), s = vsMySub(a.id);
    setTimeout(vsPaintMsgs, 0);
    return `<div class="vs-chat v8"><div class="vs-chat-h"><button type="button" class="vs-round bub" data-drag onclick="vsChatStop(); vsTab('chats')" aria-label="Kembali">${VS_ICON.back}</button>${vsAv(a.photo, a.name, 'sm', vsArtistLv(a.id))}<div><b>${escHtml(a.name)}${VS_VF}</b><small>${on ? (s ? 'Langganan sampai ' + vsDate(s.end) : 'Online') : 'Langganan berakhir'}</small></div>
        <button type="button" class="vs-round bub call" data-drag onclick="vsCallStart('${a.id}')" aria-label="Telepon">${VS_ICON.phone}</button></div>
        <div class="vs-msgs" id="vsMsgs"></div>
        ${on ? `<div class="vs-msgin"><input id="vsMsgIn" type="text" enterkeyhint="send" autocomplete="off" maxlength="1000" placeholder="Tulis pesan…" onkeydown="if(event.key==='Enter')vsSendMsg()"><button type="button" class="vs-send" onclick="vsSendMsg()" aria-label="Kirim">${VS_ICON.send}</button></div>`
            : `<div class="vs-msgin"><button type="button" class="vs-pill" style="width:100%" onclick="vsSubOpen('${a.id}')">Perpanjang langganan ${vsRp(VS_SUB_PRICE)}</button></div>`}</div>`;
}


// ======== Halaman: medpart ========
// Halaman "Official Promote Medpart" (route: medpart): poster + video YouTube untuk mempromosikan medpart.
function renderView_medpart() {
    const content = document.getElementById('appContent');
    if (currentRoute !== 'toko') stopPromoBanner();
    if (currentRoute === 'medpart') {
        const list = appData.medparts || [];
        content.innerHTML = `
            <div class="max-w-5xl mx-auto py-8 space-y-6">
                <div class="text-center mb-4">
                    <h2 class="font-serif text-3xl font-bold gold-text">Official Promote Medpart</h2>
                    <p class="text-gray-300 mt-1">Poster dan video resmi untuk mempromosikan kerja sama medpart Lorevia Entertainment.</p>
                </div>
                <div class="space-y-6">
                    ${list.length === 0 ? `
                        <div class="text-center py-14 bg-forest-800/40 rounded-2xl border border-forest-700">
                            <p class="text-gray-400 text-sm">Belum ada promosi medpart.</p>
                        </div>
                    ` : list.map(m => `
                        <article class="bg-forest-800/80 p-5 md:p-6 rounded-2xl gold-border shadow-xl space-y-4">
                            <div class="flex flex-wrap justify-between items-center gap-2 text-xs text-gold-400 font-semibold">
                                <span>${m.partner ? 'MEDPART · ' + escHtml(m.partner) : 'MEDPART'}</span><span>${escHtml(fmtDate(m.date))}</span>
                            </div>
                            <h3 class="font-serif text-xl md:text-2xl font-bold text-white">${escHtml(m.title)}</h3>
                            ${m.desc ? `<div class="text-sm text-gray-200">${renderRich(m.desc)}</div>` : ''}
                            ${(m.posters || []).length ? `
                                <div class="grid grid-cols-1 ${m.posters.length > 1 ? 'sm:grid-cols-2' : ''} ${m.posters.length > 2 ? 'lg:grid-cols-3' : ''} gap-4">
                                    ${m.posters.map((src, i) => `<img src="${escHtml(src)}" alt="Poster ${escHtml(m.title)} ${i + 1}" class="w-full rounded-xl gold-border object-cover" loading="lazy">`).join('')}
                                </div>` : ''}
                            ${(m.videos || []).length ? `
                                <div class="grid grid-cols-1 ${m.videos.length > 1 ? 'md:grid-cols-2' : ''} gap-4">
                                    ${m.videos.map(v => `<div class="space-y-1">${youtubeCardHtml(v)}</div>`).join('')}
                                </div>` : ''}
                        </article>
                    `).join('')}
                </div>
            </div>
        `;
    }
    animatePageReveal();
}


// ======== Halaman: struktur ========
// Tampilan halaman "Struktur Admin - Lorevia Entertainment" (route: struktur).

// Urutan level di bagan struktur (dari tertinggi ke terendah) — SUMBER KEBENARAN TUNGGAL,
// juga dipakai admin-dashboard.js buat validasi pas nambah/edit data.
// Tiap level berisi ARRAY jabatan — semua jabatan dalam satu level tampil SEJAJAR di bagan.
// Ini menentukan level, BUKAN urutan baris di Sheet — jadi aman ditambah data kapan saja.
const URUTAN_JABATAN_ADMIN = [
    ['Founder', 'Co-Founder'],                           // Level 1: Executive & Founder
    ['CFO'],                                              // Level 2: C-Level / Direksi
    ['Manager'],                                          // Level 3: Management / Lead
    ['Sekretaris', 'Admin'],                              // Level 4: Support & Administrasi Inti
    ['Coach Vocal', 'Coach Rap', 'Coach Dance Team'],     // Level 5: Coach
    ['PJ Medpart', 'Editor Team', 'Wording'],             // Level 6: Editor
    ['Security Team']                                     // Level 7: Staf Lapangan / Support
];

// Data struktur sekarang dari database Firestore (appData.adminStructure), diatur di Dasbor Admin → Struktur Admin.
const adminStructureLoaded = true;
async function reloadAdminStructure() {}
async function loadAdminStructure() {}

function renderView_struktur() {
    const content = document.getElementById('appContent');
    if (currentRoute !== 'toko') stopPromoBanner();
    if (currentRoute === 'struktur') {
        // Kelompokkan per level (1 = paling atas). Level diambil dari data; kalau kosong, dari urutan jabatan baku.
        const levelOf = a => {
            const n = parseInt(a.level, 10);
            if (n > 0) return n;
            const i = URUTAN_JABATAN_ADMIN.findIndex(l => l.includes(a.role));
            return i >= 0 ? i + 1 : 99;
        };
        const semuaLevel = [...new Set(appData.adminStructure.map(levelOf))]
            .sort((x, y) => x - y)
            .map(lv => appData.adminStructure.filter(a => levelOf(a) === lv));

        const roleLabel = nodes => [...new Set(nodes.map(n => n.role).filter(Boolean))].slice(0, 3).join(' & ');
        content.innerHTML = `
            <div class="max-w-6xl mx-auto py-8 space-y-8">
                <div class="text-center">
                    <h2 class="font-serif text-3xl md:text-4xl font-bold gold-text">Struktur Admin</h2>
                    <p class="text-gray-300 mt-2">Pohon kepengurusan Lorevia Entertainment: dari ranting teratas hingga akar yang menopang semuanya. Geser ke bawah untuk melihat tim muncul perlahan.</p>
                </div>
                ${appData.adminStructure.length === 0 ? `
                    <div class="text-center py-16 bg-forest-800/40 rounded-2xl border border-forest-700">
                        <p class="text-gray-400">Belum ada data struktur admin.</p>
                    </div>
                ` : `
                <div class="org-tree" data-no-reveal>
                    <div class="org-trunk"><div class="org-trunk-fill"></div></div>
                    <div class="org-crown">
                        <span class="text-5xl">🌿</span>
                        <h3 class="font-serif text-2xl font-bold gold-text mt-1">Lorevia Entertainment</h3>
                        <p class="text-xs text-gray-400 tracking-widest uppercase">Kepengurusan Inti</p>
                    </div>
                    ${semuaLevel.map((nodes, levelIdx) => `
                        <div class="org-level">
                            <span class="org-label">${escHtml(roleLabel(nodes) || ('Level ' + (levelIdx + 1)))}</span>
                            <div class="org-branch"><span class="leaf l">🌿</span><span class="leaf r">🌿</span></div>
                            <div class="org-nodes">
                                ${nodes.map((admin, i) => `
                                    <div class="org-node" style="--i:${i}">
                                        <div class="admin-card rounded-2xl border-2 border-gold-600/60 p-5 relative overflow-hidden flex flex-col items-center text-center group w-44 md:w-48 transition-shadow duration-300">
                                            <div class="admin-avatar-glow w-24 h-24 md:w-28 md:h-28 rounded-full border-2 border-gold-400 overflow-hidden mb-3 group-hover:scale-105 transition duration-300">
                                                <img src="${escHtml(admin.img || '')}" alt="${escHtml(admin.name)}" class="w-full h-full object-cover" onerror="this.onerror=null; this.classList.add('hidden'); this.nextElementSibling.classList.remove('hidden');">
                                                <div class="hidden w-full h-full items-center justify-center bg-forest-700 text-gold-400 text-3xl font-bold">${escHtml((admin.name || '?').charAt(0).toUpperCase())}</div>
                                            </div>
                                            <p class="text-[11px] font-bold text-gray-300 uppercase tracking-widest">${escHtml(admin.role)}</p>
                                            <h3 class="font-serif text-lg font-bold gold-text leading-tight mt-0.5">${escHtml(admin.name)}</h3>
                                        </div>
                                    </div>
                                `).join('')}
                            </div>
                        </div>
                    `).join('')}
                    <div class="org-roots">
                        <svg class="roots" viewBox="0 0 560 120" aria-hidden="true">
                            <path pathLength="1" d="M280 0 C280 40 240 50 150 70 C110 80 70 90 40 118"/>
                            <path pathLength="1" d="M280 0 C280 45 330 55 420 72 C460 82 500 92 530 118"/>
                            <path pathLength="1" d="M280 0 C275 50 270 80 275 118"/>
                            <path pathLength="1" d="M280 20 C250 55 200 70 190 110"/>
                            <path pathLength="1" d="M280 20 C320 55 370 70 385 112"/>
                        </svg>
                        <p class="font-serif text-lg font-bold gold-text">Akar kami: kerja sama, kreativitas &amp; kekeluargaan</p>
                    </div>
                </div>
                `}
            </div>
        `;
    }
    animatePageReveal();
}

// ======== Halaman: guestbox ========
// Tampilan halaman "Guest Box - Lorevia Entertainment" (route: guestbox).
// Markup disalin apa adanya dari versi satu file.
let guestBoxLoaded = false;

function escapeGuestBoxHtml(value) {
    return String(value || '').replace(/[&<>"']/g, character => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[character]));
}

async function loadGuestBoxes() { guestBoxLoaded = true; }   // pesan tamu dimuat dari Firestore

        function renderView_guestbox() {
            const content = document.getElementById('appContent');
            if (currentRoute !== 'toko') stopPromoBanner();
            if (currentRoute === 'guestbox') {
                content.innerHTML = `
                    <div class="max-w-3xl mx-auto py-8 space-y-8">
                        <div class="text-center">
                            <h2 class="font-serif text-3xl font-bold gold-text">Guest Box (Buku Tamu)</h2>
                            <p class="text-gray-300 mt-1">Tinggalkan pesan, kesan, atau dukungan Anda untuk Lorevia Entertainment.</p>
                        </div>
                        
                        <!-- Form Guest Box -->
                        <div class="bg-forest-800/80 p-6 rounded-2xl gold-border shadow-xl">
                            <form onsubmit="submitGuest(event)" class="space-y-4">
                                <div>
                                    <label class="block text-sm font-medium text-gold-400 mb-1">Nama / Panggilan</label>
                                    <input type="text" id="gName" required class="w-full px-4 py-3 rounded-xl bg-forest-900 border border-forest-600 focus:border-gold-500 text-white outline-none">
                                </div>
                                <div>
                                    <label class="block text-sm font-medium text-gold-400 mb-1">Pesan / Kesan</label>
                                    <textarea id="gMsg" rows="3" required class="w-full px-4 py-3 rounded-xl bg-forest-900 border border-forest-600 focus:border-gold-500 text-white outline-none"></textarea>
                                </div>
                                <button type="submit" class="w-full py-3 rounded-xl bg-gold-600 hover:bg-gold-500 text-black font-bold transition shadow-lg">Kirim Pesan</button>
                            </form>
                        </div>

                        <!-- List of Messages -->
                        <div class="space-y-4">
                            <h3 class="font-serif text-xl font-bold gold-text border-b border-forest-700 pb-2">Pesan Pengunjung</h3>
                            ${appData.guestBoxes.slice().reverse().map(gb => `
                                <div class="bg-forest-800/60 p-5 rounded-xl border border-forest-700 shadow-md space-y-2">
                                    <div class="flex justify-between items-center text-xs text-gray-400">
                                        <span class="font-bold text-gold-400 text-sm">${escapeGuestBoxHtml(gb.name)}</span>
                                        <span>${escapeGuestBoxHtml(gb.date)}</span>
                                    </div>
                                    <p class="text-sm text-gray-200">${escapeGuestBoxHtml(gb.message)}</p>
                                </div>
                            `).join('')}
                        </div>
                    </div>
                `;
            }
            animatePageReveal();
        }


// ======== Halaman: aktivitas ========
// Halaman "Aktivitas" (route: aktivitas): Video dan Audio dalam satu halaman, masing-masing fitur sendiri (tab).
let activityTab = 'video';
function setActivityTab(t) { activityTab = t === 'audio' ? 'audio' : 'video'; renderView(); window.scrollTo({ top: 0 }); }

function renderView_aktivitasInner() {
    const real = currentRoute;
    currentRoute = activityTab === 'audio' ? 'audio-playlist' : 'video-playlist';
    try { (activityTab === 'audio' ? PAGE_RENDERERS['audio-playlist'] : PAGE_RENDERERS['video-playlist'])(); }
    finally { currentRoute = real; }
    const first = document.getElementById('appContent').firstElementChild;
    if (first) first.insertAdjacentHTML('afterbegin', `
        <div class="activity-tabs" data-no-reveal>
            <button onclick="setActivityTab('video')" class="${activityTab === 'video' ? 'on' : ''}">🎬 Video</button>
            <button onclick="setActivityTab('audio')" class="${activityTab === 'audio' ? 'on' : ''}">🎧 Audio</button>
        </div>`);
}
function renderView_aktivitas() {
    if (currentRoute === 'aktivitas') renderView_aktivitasInner();
}


