/* ################ Efek suara ################ */
// Efek suara antarmuka (disintesis lewat WebAudio, tanpa file audio). Baru aktif setelah pengguna menyentuh layar
// (aturan browser), dibatasi lajunya supaya tidak berisik, dan bisa dimatikan lewat tombol speaker.
(function () {
    var ctx = null, last = {}, muted = false;
    try { muted = localStorage.getItem('lorevia_mute') === '1'; } catch (e) {}
    function ensure() {
        if (ctx) return ctx;
        var AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return null;
        try { ctx = new AC(); } catch (e) { ctx = null; }
        return ctx;
    }
    function resume() { var c = ensure(); if (c && c.state === 'suspended') c.resume().catch(function () {}); }
    ['pointerdown', 'touchstart', 'keydown'].forEach(function (ev) {
        window.addEventListener(ev, resume, { passive: true, capture: true });
    });
    function tone(c, t, freq, dur, vol, type, slideTo) {
        var o = c.createOscillator(), g = c.createGain();
        o.type = type || 'sine';
        o.frequency.setValueAtTime(freq, t);
        if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(vol, t + 0.012);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        o.connect(g); g.connect(c.destination);
        o.start(t); o.stop(t + dur + 0.02);
    }
    var GAP = { tap: 40, nav: 60, pop: 90, soft: 90 };
    window.uiSound = function (kind) {
        if (muted) return;
        var c = ensure();
        if (!c || c.state !== 'running') return;
        var now = Date.now(), k = kind || 'tap';
        if (now - (last[k] || 0) < (GAP[k] || 60)) return;
        last[k] = now;
        var t = c.currentTime;
        try {
            if (k === 'nav') { tone(c, t, 523, 0.11, 0.07, 'triangle'); tone(c, t + 0.07, 784, 0.16, 0.07, 'triangle'); }
            else if (k === 'pop') { tone(c, t, 420 + Math.random() * 120, 0.12, 0.035, 'sine', 900); }
            else { tone(c, t, 660, 0.07, 0.05, 'triangle', 440); }
        } catch (e) {}
    };
    window.uiSoundMuted = function () { return muted; };
    window.toggleUiSound = function () {
        muted = !muted;
        try { localStorage.setItem('lorevia_mute', muted ? '1' : '0'); } catch (e) {}
        document.querySelectorAll('[data-sound-btn]').forEach(function (b) { b.classList.toggle('is-muted', muted); b.setAttribute('aria-pressed', String(!muted)); });
        if (!muted) { resume(); setTimeout(function () { window.uiSound('nav'); }, 30); }
    };
    // Suara untuk semua tombol navigasi & tombol utama
    document.addEventListener('click', function (e) {
        var t = e.target && e.target.closest ? e.target.closest('.nav-pill, .app-tab, .app-tile, .tab-btn, .activity-tabs button, .chip, [data-sound]') : null;
        if (t) { window.uiSound(t.matches('.nav-pill, .app-tab, .app-tile') ? 'nav' : 'tap'); return; }
        var b = e.target && e.target.closest ? e.target.closest('button, a[href]') : null;
        if (b && !b.closest('#sidebarOverlay')) window.uiSound('tap');
    }, true);
})();


