// Cangkang situs: penanda halaman aktif, tombol bulat pemilih aplikasi (Dispatch / Lorevia Verse), dan ajakan mengunjungi Lorevia Verse.
var LOGO_VERSE = '<img class="lv-img" alt="Lorevia Verse" src="data:image/jpeg;base64,">';
var LOGO_DISPATCH = '<img class="lv-img lv-dp" alt="Dispatch" src="data:image/jpeg;base64,">';
(function () {
    function setRoute(r) { document.documentElement.setAttribute('data-route', r || 'beranda'); var sw = document.getElementById('appSwitch'); if (sw) sw.style.display = (r === 'admin-dashboard') ? 'none' : ''; }
    window.setShellRoute = setRoute;
    // bungkus showRoute agar tiap pindah halaman memperbarui penanda
    if (typeof showRoute === 'function') {
        var _sr = showRoute;
        showRoute = function (route) { setRoute(route); window.closeSwitcher && window.closeSwitcher(); return _sr.apply(this, arguments); };
    }
    function build() {
        if (document.getElementById('appSwitch')) return;
        var b = document.createElement('button');
        b.id = 'appSwitch'; b.type = 'button'; b.setAttribute('aria-label', 'Pilih aplikasi: Dispatch atau Lorevia Verse');
        b.innerHTML = '<span class="as-ico">' + LOGO_VERSE + '</span><span class="as-chev">&lsaquo;&rsaquo;</span>';
        document.body.appendChild(b);
        var sx = null, moved = false;
        b.addEventListener('pointerdown', function (e) { sx = e.clientX; moved = false; });
        b.addEventListener('pointermove', function (e) { if (sx !== null && Math.abs(e.clientX - sx) > 24) { moved = true; sx = null; openSwitcher(); } });
        b.addEventListener('pointerup', function () { sx = null; });
        b.addEventListener('click', function () { if (!moved) openSwitcher(); moved = false; });
        var s = document.createElement('div');
        s.id = 'switcher';
        s.innerHTML = '<div class="sw-sheet"><div class="sw-grip"></div><h3>Pilih aplikasi</h3><p>Geser &lsaquo; &rsaquo; untuk berpindah, lalu pilih yang ingin dibuka.</p>' +
            '<div class="sw-row">' +
            '<button type="button" class="sw-card verse" onclick="goApp(\'verse\')"><span class="sw-logo">' + LOGO_VERSE + '</span><b>Lorevia Verse</b><i>Akun grup &amp; artis, story, store</i></button>' +
            '<button type="button" class="sw-card disp" onclick="goApp(\'dispatch\')"><span class="sw-logo">' + LOGO_DISPATCH + '</span><b>Lorevia Dispatch</b><i>Berita resmi agensi</i></button></div>' +
            '<button type="button" class="sw-home" onclick="goApp(\'beranda\')">Kembali ke situs utama</button></div>';
        s.addEventListener('click', function (e) { if (e.target === s) closeSwitcher(); });
        document.body.appendChild(s);
    }
    function openSwitcher() { var s = document.getElementById('switcher'); if (s) s.classList.add('open'); }
    window.openSwitcher = openSwitcher;
    window.closeSwitcher = function () { var s = document.getElementById('switcher'); if (s) s.classList.remove('open'); };
    window.goApp = function (r) { window.closeSwitcher(); navigate(r); };

    // Ajakan mengunjungi Lorevia Verse (sekali per sesi)
    function invite() {
        try { if (localStorage.getItem('lorevia_verse_invite') || sessionStorage.getItem('lorevia_verse_invite')) return; } catch (e) {}
        var r = document.documentElement.getAttribute('data-route');
        if (r === 'admin-dashboard' || r === 'verse' || r === 'dispatch') return;
        try { sessionStorage.setItem('lorevia_verse_invite', '1'); localStorage.setItem('lorevia_verse_invite', '1'); } catch (e) {}
        var d = document.createElement('div');
        d.id = 'verseInvite';
        d.innerHTML = '<div class="vi-card"><span class="vi-logo">' + LOGO_VERSE + '</span><h3>Kunjungi Lorevia Verse</h3><p>Ikuti akun grup &amp; artis Lorevia, lihat story, dan temukan album serta merchandise resmi.</p>' +
            '<button type="button" class="vi-go" id="viGo">Kunjungi sekarang</button><button type="button" class="vi-later" id="viLater">Nanti saja</button></div>';
        document.body.appendChild(d);
        requestAnimationFrame(function () { d.classList.add('show'); });
        function close() { d.classList.remove('show'); setTimeout(function () { d.remove(); }, 350); }
        document.getElementById('viGo').onclick = function () { close(); navigate('verse'); };
        document.getElementById('viLater').onclick = close;
        d.addEventListener('click', function (e) { if (e.target === d) close(); });
    }
    function init() {
        setRoute(window.PAGE_ROUTE || (typeof currentRoute !== 'undefined' ? currentRoute : 'beranda'));
        build();
        setRoute(typeof currentRoute !== 'undefined' ? currentRoute : 'beranda');
        setTimeout(invite, 1200);
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ################ Mode aplikasi & unduh ################ */
// Mode aplikasi: banner unduh (PWA), tombol suara, tab bar bawah & menu "launcher" saat dipasang sebagai aplikasi.
(function () {
    var ADMIN = window.APP_KIND === 'admin';
    var APP_FILE = ADMIN ? '/lorevia-admin.html' : '/lorevia-app.html';
    var DKEY = ADMIN ? 'lorevia_admin_dismiss' : 'lorevia_app_dismiss';
    function modeClass() { return ADMIN ? 'admin-app' : 'app-mode'; }
    function standalone() {
        return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || window.navigator.standalone === true;
    }
    var deferred = null;
    window.addEventListener('beforeinstallprompt', function (e) { e.preventDefault(); deferred = e; showBanner(); });
    window.addEventListener('appinstalled', function () { deferred = null; hideBanner(true); document.documentElement.classList.add(modeClass()); build(); });

    function isIOS() { return /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1); }
    function dismissed() { try { return Date.now() < +localStorage.getItem(DKEY); } catch (e) { return false; } }

    function bannerHtml() {
        return '<div class="ib-card">' +
            '<img class="ib-logo" src="/logo.png" alt="Logo Lorevia Entertainment">' +
            '<div class="ib-text"><b>' + (ADMIN ? 'Lorevia Admin' : 'Lorevia Entertainment') + '</b><span>' + (ADMIN ? 'Aplikasi khusus admin untuk mengelola konten.' : 'Pasang aplikasinya: lebih cepat &amp; dibuka tanpa browser.') + '</span></div>' +
            '<button class="ib-go" id="ibGo" aria-label="Unduh aplikasi"><svg class="ico" aria-hidden="true"><use href="#download"></use></svg><span>Unduh Aplikasi</span></button>' +
            '<button class="ib-x" id="ibX" aria-label="Tutup">&times;</button></div>';
    }
    function showBanner() {
        if (standalone() || dismissed() || document.getElementById('installBanner')) return;
        var d = document.createElement('div');
        d.id = 'installBanner'; d.innerHTML = bannerHtml();
        d.addEventListener('click', function (e) { if (e.target === d) hideBanner(false); });
        document.body.appendChild(d);
        requestAnimationFrame(function () { d.classList.add('show'); });
        document.getElementById('ibGo').onclick = installNow;
        document.getElementById('ibX').onclick = function () { hideBanner(false); };
    }
    function hideBanner(done) {
        var d = document.getElementById('installBanner');
        if (d) { d.classList.remove('show'); setTimeout(function () { d.remove(); }, 400); }
        if (!done) { try { localStorage.setItem(DKEY, String(Date.now() + 86400000)); } catch (e) {} }
    }
    function installNow() {
        if (deferred) {
            deferred.prompt();
            deferred.userChoice.finally(function () { deferred = null; hideBanner(true); });
            return;
        }
        // Tanpa dukungan pemasangan langsung (iOS / browser lain): unduh file pintasan otomatis + petunjuk.
        var a = document.createElement('a'); a.href = APP_FILE; a.download = ADMIN ? 'Lorevia-Admin.html' : 'Lorevia-Entertainment.html';
        document.body.appendChild(a); a.click(); a.remove();
        var msg = isIOS()
            ? 'Di iPhone/iPad: buka situs ini di Safari, ketuk tombol Bagikan lalu pilih "Tambah ke Layar Utama".'
            : 'File aplikasi telah diunduh. Jika muncul ikon pasang di kolom alamat browser, klik untuk memasangnya; atau buka menu browser lalu pilih "Instal aplikasi".';
        alert(msg);
    }
    window.installLoreviaApp = installNow;
    // Tampilkan popup unduh di semua browser (tidak hanya yang memicu beforeinstallprompt)
    window.addEventListener('load', function () { setTimeout(showBanner, 2500); });

    // Tombol suara + tombol unduh di header
    function headerButtons() {
        var box = document.querySelector('header .flex.items-center.space-x-2');
        if (!box || document.getElementById('soundBtn')) return;
        var s = document.createElement('button');
        s.id = 'soundBtn'; s.setAttribute('data-sound-btn', ''); s.setAttribute('aria-label', 'Suara');
        s.className = 'snd-btn p-2.5 rounded-full bg-forest-800 gold-border text-gold-400 hover:bg-forest-700 transition';
        s.innerHTML = '<svg class="ico on" aria-hidden="true"><use href="#headphones"></use></svg><span class="slash"></span>';
        s.onclick = function () { window.toggleUiSound(); };
        if (window.uiSoundMuted && window.uiSoundMuted()) s.classList.add('is-muted');
        box.insertBefore(s, box.firstChild);
    }

    // ---- Tampilan aplikasi: tab bar bawah + menu launcher ----
    var TABS = [['beranda', 'home', 'Beranda'], ['aktivitas', 'movie-open', 'Aktivitas'], ['member', 'star', 'Artis'], ['__profil', 'people', 'Profil']];
    var TILES = [['about', 'flower', 'About'], ['history', 'history', 'History'], ['kerjasama', 'people', 'Kerja Sama'], ['aktivitas', 'movie-open', 'Aktivitas'],
        ['struktur', 'butterfly', 'Struktur'], ['member', 'star', 'Members'], ['pengumuman', 'bullhorn', 'Pengumuman'], ['achievement', 'trophy', 'Achievement'],
        ['medpart', 'play-circle', 'Promote'], ['toko', 'shopping', 'Store'], ['guestbox', 'mailbox', 'Guest Box']];
    function build() {
        if (ADMIN || !document.documentElement.classList.contains('app-mode') || document.getElementById('appTabs')) return;
        var bar = document.createElement('nav');
        bar.id = 'appTabs';
        bar.innerHTML = TABS.map(function (t) {
            return '<button class="app-tab" data-route="' + t[0] + '" onclick="' + (t[0] === '__profil' ? 'openProfil()' : 'navigate(\'' + t[0] + '\')') + '"><svg class="ico" aria-hidden="true"><use href="#' + t[1] + '"></use></svg><span>' + t[2] + '</span></button>';
        }).join('') + '<button class="app-tab" data-route="__menu" onclick="openAppMenu()"><svg class="ico" aria-hidden="true"><use href="#people"></use></svg><span>Menu</span></button>';
        document.body.appendChild(bar);
        var m = document.createElement('div');
        m.id = 'appMenu';
        m.innerHTML = '<div class="am-sheet"><div class="am-grip"></div><h3>Menu Lorevia</h3><div class="am-grid">' + TILES.map(function (t) {
            return '<button class="app-tile" onclick="closeAppMenu(); navigate(\'' + t[0] + '\')"><span class="at-ico"><svg class="ico" aria-hidden="true"><use href="#' + t[1] + '"></use></svg></span><span>' + t[2] + '</span></button>';
        }).join('') + '</div></div>';
        m.addEventListener('click', function (e) { if (e.target === m) closeAppMenu(); });
        document.body.appendChild(m);
        window.markActiveNav && window.markActiveNav();
    }
    window.openAppMenu = function () { var m = document.getElementById('appMenu'); if (m) m.classList.add('open'); };
    window.closeAppMenu = function () { var m = document.getElementById('appMenu'); if (m) m.classList.remove('open'); };
    var prevMark = window.markActiveNav;
    window.markActiveNav = function () {
        if (prevMark) prevMark();
        document.querySelectorAll('#appTabs .app-tab').forEach(function (b) { b.classList.toggle('is-active', b.dataset.route === window.PAGE_ROUTE); });
    };

    function init() {
        if (standalone()) document.documentElement.classList.add(modeClass());
        headerButtons(); build();
        if ('serviceWorker' in navigator && location.protocol.indexOf('http') === 0) {
            navigator.serviceWorker.register('/sw.js').catch(function () {});
        }
        // Beri banner juga di browser yang tidak mengirim beforeinstallprompt (mis. iOS)
        setTimeout(function () { if (!deferred) showBanner(); }, 2500);
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();

